/* (2026-11-24) three more from The Cleveland Museum of Art (CC0): Dasavanta’s Tuti-nama chess monkey 1962.279.32.b, Teniers’s Game of Backgammon 1943.377, the Imari go dish 1964.260 */
(T => { const A = {"tutinama": {"ja": {"title": "チェス仲間の王子の手をかむ猿（『トゥーティー・ナーマ（オウムの物語）』より）", "artist": "ダサヴァンタ", "date": "1560年ごろ", "place": "インド（アクバルのムガル宮廷）", "game": "チェス", "medium": "紙に不透明水彩・墨・金", "size": "20×14.2cm（絵の部分 10.2×10.6cm）", "credit": "A・ディーン・ペリー夫人寄贈、1962年", "p": ["ムガル帝国のアクバル帝の宮廷で作られた物語集『トゥーティー・ナーマ（オウムの物語）』の挿絵です。母オウムが子どもたちに、狐の子のような違う種類の生き物と仲よくしてはいけないと教えるために語る話のひとつ。チェスが上手な猿が、王子といつもチェスを指していました。", "ある日、王子が客を招いた席で猿が失礼な冗談を言い、王子に平手打ちされます。怒った猿は王子の手にかみつきました。右の外では召使いが料理の支度をし、客たちは驚いて見ています。下の書き込みには、のちにムガル宮廷で最も名高い画家の一人になるダサヴァンタの名があります。若い彼は、絵の下に涼しい青の色を一層塗っていたそうです。"], "spots": [["猿", "王子の手にかみつく猿。王子のチェス仲間でした。"], ["王子", "手をかまれた王子。"], ["チェス盤", "赤い升目の盤が床に置かれています。"], ["驚く客たち", "宴に招かれた客たち。"], ["料理の支度", "外で鍋を火にかける召使いたち。"], ["ペルシア語の本文", "上の枠には物語の文がペルシア語で書かれています。"]]}, "en": {"title": "The wounded monkey bites the hand of the prince, his chessmate (from a Tuti-nama, Tales of a Parrot)", "artist": "Dasavanta", "date": "c. 1560", "place": "India (Mughal court of Akbar)", "game": "Chess", "medium": "Gum tempera, ink and gold on paper", "size": "20 × 14.2 cm (painting 10.2 × 10.6 cm)", "credit": "Gift of Mrs. A. Dean Perry, 1962", "p": ["An illustration from the Tuti-nama, the “Tales of a Parrot”, made at the court of the Mughal emperor Akbar. It is one of the stories a mother parrot tells her chicks to warn them against friendships with other kinds of creatures, such as the fox cubs. In it, a monkey who was good at chess often played with a prince.", "One day, with guests present, the monkey made an unkind joke and the prince slapped him — and the monkey bit the prince’s hand. Outside on the right, servants prepare food while the astonished guests look on. An inscription at the bottom names Dasavanta, who later became one of the most celebrated masters at the Mughal court; as a young artist he laid a cool blue layer under his painting."], "spots": [["The monkey", "Biting the prince’s hand — his partner at chess."], ["The prince", "The prince whose hand is bitten."], ["The chessboard", "A red-squared board on the floor."], ["The astonished guests", "The guests invited to the gathering."], ["Preparing food", "Servants outside, setting pots on the fire."], ["The Persian text", "Above, the story is written out in Persian."]]}, "zh": {"title": "受伤的猴子咬了棋友王子的手（《鹦鹉故事》插图）", "artist": "达萨万塔", "date": "约1560年", "place": "印度（阿克巴的莫卧儿宫廷）", "game": "国际象棋", "medium": "纸本水粉、墨、金", "size": "20×14.2厘米（画面10.2×10.6厘米）", "credit": "A·迪恩·佩里夫人捐赠，1962年", "p": ["这是莫卧儿帝国阿克巴宫廷制作的故事集《鹦鹉故事》（Tuti-nama）的插图。母鹦鹉给孩子们讲故事，告诫它们不要和狐狸崽这样不同种类的动物交朋友，这是其中一则：一只擅长国际象棋的猴子，常常和王子下棋。", "有一天王子宴客，猴子在席上开了个失礼的玩笑，被王子打了一巴掌，猴子便咬了王子的手。右边屋外仆人在准备饭菜，客人们看得目瞪口呆。下方的题记写着达萨万塔的名字，他后来成为莫卧儿宫廷最著名的画家之一；年轻的他在画面下先涂了一层清凉的蓝色。"], "spots": [["猴子", "咬住王子的手——它是王子的棋友。"], ["王子", "被咬了手的王子。"], ["棋盘", "放在地上的红格棋盘。"], ["吃惊的客人", "应邀赴宴的客人们。"], ["准备饭菜", "外面把锅架在火上的仆人们。"], ["波斯文", "上方框里用波斯文写着故事。"]]}, "zh-TW": {"title": "受傷的猴子咬了棋友王子的手（《鸚鵡故事》插圖）", "artist": "達薩萬塔", "date": "約1560年", "place": "印度（阿克巴的蒙兀兒宮廷）", "game": "西洋棋", "medium": "紙本水粉、墨、金", "size": "20×14.2公分（畫面10.2×10.6公分）", "credit": "A·迪恩·佩里夫人捐贈，1962年", "p": ["這是蒙兀兒帝國阿克巴宮廷製作的故事集《鸚鵡故事》（Tuti-nama）的插圖。母鸚鵡給孩子們講故事，告誡牠們不要和狐狸崽這樣不同種類的動物交朋友，這是其中一則：一隻擅長西洋棋的猴子，常常和王子下棋。", "有一天王子宴客，猴子在席上開了個失禮的玩笑，被王子打了一巴掌，猴子便咬了王子的手。右邊屋外僕人在準備飯菜，客人們看得目瞪口呆。下方的題記寫著達薩萬塔的名字，他後來成為蒙兀兒宮廷最著名的畫家之一；年輕的他在畫面下先塗了一層清涼的藍色。"], "spots": [["猴子", "咬住王子的手——牠是王子的棋友。"], ["王子", "被咬了手的王子。"], ["棋盤", "放在地上的紅格棋盤。"], ["吃驚的客人", "應邀赴宴的客人們。"], ["準備飯菜", "外面把鍋架在火上的僕人們。"], ["波斯文", "上方框裡用波斯文寫著故事。"]]}, "ko": {"title": "체스 친구인 왕자의 손을 무는 원숭이(『투티나마(앵무새 이야기)』에서)", "artist": "다사반타", "date": "1560년경", "place": "인도(아크바르의 무굴 궁정)", "game": "체스", "medium": "종이에 구아슈·먹·금", "size": "20×14.2cm(그림 부분 10.2×10.6cm)", "credit": "A. 딘 페리 부인 기증, 1962년", "p": ["무굴 제국 아크바르 황제의 궁정에서 만든 이야기책 『투티나마(앵무새 이야기)』의 삽화입니다. 엄마 앵무새가 새끼들에게 여우 새끼 같은 다른 종류의 동물과 친하게 지내지 말라고 일러 주며 들려주는 이야기 가운데 하나로, 체스를 잘 두는 원숭이가 늘 왕자와 체스를 두었습니다.", "어느 날 왕자가 손님을 초대한 자리에서 원숭이가 무례한 농담을 하자 왕자가 뺨을 때렸고, 원숭이는 왕자의 손을 물었습니다. 오른쪽 바깥에서는 하인들이 음식을 준비하고 손님들은 놀라서 바라봅니다. 아래 글씨에는 훗날 무굴 궁정에서 가장 이름난 화가가 되는 다사반타의 이름이 있습니다. 젊은 그는 그림 밑에 시원한 파란색을 한 겹 깔았다고 합니다."], "spots": [["원숭이", "왕자의 손을 무는 원숭이. 왕자의 체스 친구였습니다."], ["왕자", "손을 물린 왕자."], ["체스판", "바닥에 놓인 빨간 칸의 판."], ["놀란 손님들", "잔치에 초대된 손님들."], ["음식 준비", "밖에서 솥을 불에 올리는 하인들."], ["페르시아어 본문", "위 칸에는 이야기가 페르시아어로 쓰여 있습니다."]]}, "es": {"title": "El mono herido muerde la mano del príncipe, su compañero de ajedrez (del Tuti-nama, Cuentos de un loro)", "artist": "Dasavanta", "date": "h. 1560", "place": "India (corte mogol de Akbar)", "game": "Ajedrez", "medium": "Témpera, tinta y oro sobre papel", "size": "20 × 14,2 cm (pintura 10,2 × 10,6 cm)", "credit": "Donación de la Sra. A. Dean Perry, 1962", "p": ["Una ilustración del Tuti-nama, los «Cuentos de un loro», hecho en la corte del emperador mogol Akbar. Es uno de los relatos con que una madre loro advierte a sus polluelos contra las amistades con otras especies, como los cachorros de zorro. En él, un mono que jugaba bien al ajedrez solía jugar con un príncipe.", "Un día, delante de unos invitados, el mono hizo una broma grosera y el príncipe le dio una bofetada; el mono le mordió la mano. Fuera, a la derecha, los criados preparan la comida mientras los invitados miran asombrados. Una inscripción abajo nombra a Dasavanta, que llegaría a ser uno de los maestros más célebres de la corte mogol; de joven puso una capa de azul frío bajo su pintura."], "spots": [["El mono", "Muerde la mano del príncipe, su compañero de ajedrez."], ["El príncipe", "El príncipe mordido."], ["El tablero", "Un tablero de casillas rojas en el suelo."], ["Los invitados asombrados", "Los invitados a la reunión."], ["La comida", "Criados que ponen ollas al fuego afuera."], ["El texto persa", "Arriba, la historia escrita en persa."]]}, "fr": {"title": "Le singe blessé mord la main du prince, son partenaire d’échecs (d’un Tuti-nama, Contes d’un perroquet)", "artist": "Dasavanta", "date": "vers 1560", "place": "Inde (cour moghole d’Akbar)", "game": "Échecs", "medium": "Tempera, encre et or sur papier", "size": "20 × 14,2 cm (peinture 10,2 × 10,6 cm)", "credit": "Don de Mme A. Dean Perry, 1962", "p": ["Une illustration du Tuti-nama, les « Contes d’un perroquet », réalisé à la cour de l’empereur moghol Akbar. C’est l’une des histoires qu’une mère perroquet raconte à ses petits pour les détourner des amitiés avec d’autres espèces, comme les renardeaux. Un singe habile aux échecs jouait souvent avec un prince.", "Un jour, devant des invités, le singe fit une plaisanterie blessante ; le prince le gifla, et le singe lui mordit la main. Dehors, à droite, des serviteurs préparent le repas sous les yeux des invités stupéfaits. Une inscription en bas nomme Dasavanta, qui deviendra l’un des maîtres les plus célèbres de la cour moghole ; jeune, il posa une couche de bleu froid sous sa peinture."], "spots": [["Le singe", "Il mord la main du prince, son partenaire aux échecs."], ["Le prince", "Le prince mordu."], ["L’échiquier", "Un échiquier à cases rouges posé au sol."], ["Les invités stupéfaits", "Les invités de la réception."], ["Le repas", "Dehors, des serviteurs mettent des marmites sur le feu."], ["Le texte persan", "En haut, l’histoire écrite en persan."]]}, "pt": {"title": "O macaco ferido morde a mão do príncipe, seu parceiro de xadrez (de um Tuti-nama, Contos de um papagaio)", "artist": "Dasavanta", "date": "c. 1560", "place": "Índia (corte mogol de Akbar)", "game": "Xadrez", "medium": "Têmpera, tinta e ouro sobre papel", "size": "20 × 14,2 cm (pintura 10,2 × 10,6 cm)", "credit": "Doação da Sra. A. Dean Perry, 1962", "p": ["Uma ilustração do Tuti-nama, os «Contos de um papagaio», feito na corte do imperador mogol Akbar. É uma das histórias que uma mãe papagaio conta aos filhotes para alertá-los contra amizades com outras espécies, como os filhotes de raposa. Nela, um macaco bom no xadrez jogava sempre com um príncipe.", "Um dia, diante de convidados, o macaco fez uma piada grosseira e o príncipe lhe deu um tapa — e o macaco mordeu a mão do príncipe. Do lado de fora, à direita, criados preparam a comida enquanto os convidados olham espantados. Uma inscrição embaixo nomeia Dasavanta, que se tornaria um dos mestres mais célebres da corte mogol; jovem, ele pôs uma camada de azul frio sob a pintura."], "spots": [["O macaco", "Morde a mão do príncipe, seu parceiro de xadrez."], ["O príncipe", "O príncipe mordido."], ["O tabuleiro", "Um tabuleiro de casas vermelhas no chão."], ["Os convidados espantados", "Os convidados da reunião."], ["A comida", "Do lado de fora, criados põem panelas no fogo."], ["O texto persa", "No alto, a história escrita em persa."]]}, "de": {"title": "Der verwundete Affe beißt dem Prinzen, seinem Schachpartner, in die Hand (aus einem Tuti-nama, Erzählungen eines Papageis)", "artist": "Dasavanta", "date": "um 1560", "place": "Indien (Mogulhof Akbars)", "game": "Schach", "medium": "Gouache, Tusche und Gold auf Papier", "size": "20 × 14,2 cm (Bild 10,2 × 10,6 cm)", "credit": "Schenkung von Mrs. A. Dean Perry, 1962", "p": ["Eine Illustration aus dem Tuti-nama, den „Erzählungen eines Papageis“, entstanden am Hof des Mogulkaisers Akbar. Es ist eine der Geschichten, mit denen eine Papageienmutter ihre Jungen vor Freundschaften mit anderen Tierarten warnt – etwa mit den Fuchswelpen. Darin spielte ein schachkundiger Affe oft mit einem Prinzen.", "Eines Tages machte der Affe vor Gästen einen bösen Scherz; der Prinz ohrfeigte ihn, und der Affe biss ihm in die Hand. Rechts draußen bereiten Diener das Essen, während die Gäste verblüfft zusehen. Eine Inschrift unten nennt Dasavanta, der später zu den berühmtesten Meistern am Mogulhof gehörte; als junger Maler legte er eine kühle blaue Schicht unter sein Bild."], "spots": [["Der Affe", "Er beißt dem Prinzen, seinem Schachpartner, in die Hand."], ["Der Prinz", "Der gebissene Prinz."], ["Das Schachbrett", "Ein Brett mit roten Feldern auf dem Boden."], ["Die verblüfften Gäste", "Die geladenen Gäste."], ["Das Essen", "Draußen setzen Diener Töpfe aufs Feuer."], ["Der persische Text", "Oben steht die Geschichte auf Persisch."]]}, "ru": {"title": "Раненая обезьяна кусает руку принца, своего партнёра по шахматам (из «Тути-наме», «Сказок попугая»)", "artist": "Дасаванта", "date": "около 1560 г.", "place": "Индия (двор Великого Могола Акбара)", "game": "Шахматы", "medium": "Гуашь, тушь и золото на бумаге", "size": "20 × 14,2 см (роспись 10,2 × 10,6 см)", "credit": "Дар миссис А. Дин Перри, 1962", "p": ["Иллюстрация к «Тути-наме», «Сказкам попугая», созданной при дворе могольского императора Акбара. Это одна из историй, которыми мать-попугаиха предостерегает птенцов от дружбы с другими видами — например, с лисятами. В ней обезьяна, искусная в шахматах, часто играла с принцем.", "Однажды при гостях обезьяна грубо пошутила, принц дал ей пощёчину — и обезьяна укусила его за руку. Справа, снаружи, слуги готовят еду, а гости изумлённо смотрят. Надпись внизу называет Дасаванту, позднее одного из самых прославленных мастеров могольского двора; молодым художником он клал под живопись слой прохладного синего."], "spots": [["Обезьяна", "Кусает руку принца, своего партнёра по шахматам."], ["Принц", "Укушенный принц."], ["Шахматная доска", "Доска с красными клетками на полу."], ["Изумлённые гости", "Гости, приглашённые на приём."], ["Готовят еду", "Снаружи слуги ставят котлы на огонь."], ["Персидский текст", "Наверху история записана по-персидски."]]}, "tr": {"title": "Yaralı maymun satranç arkadaşı prensin elini ısırıyor (Tuti-nâme, “Papağanın Masalları”ndan)", "artist": "Dasavanta", "date": "1560 dolayları", "place": "Hindistan (Ekber’in Babür sarayı)", "game": "Satranç", "medium": "Kâğıt üzerine guaj, mürekkep ve altın", "size": "20 × 14,2 cm (resim 10,2 × 10,6 cm)", "credit": "Bayan A. Dean Perry bağışı, 1962", "p": ["Babür imparatoru Ekber’in sarayında hazırlanan Tuti-nâme’den (“Papağanın Masalları”) bir resim. Anne papağanın, yavrularını tilki yavruları gibi başka türden hayvanlarla dostluk kurmaktan sakındırmak için anlattığı öykülerden biri: satrançta usta bir maymun sık sık bir prensle satranç oynarmış.", "Bir gün konukların önünde maymun kaba bir şaka yapmış, prens onu tokatlamış, maymun da prensin elini ısırmış. Sağda, dışarıda hizmetkârlar yemek hazırlarken konuklar şaşkınlıkla bakıyor. Alttaki yazı, sonradan Babür sarayının en ünlü ustalarından biri olacak Dasavanta’nın adını veriyor; genç ressam resminin altına serin bir mavi katman sürmüş."], "spots": [["Maymun", "Satranç arkadaşı prensin elini ısırıyor."], ["Prens", "Eli ısırılan prens."], ["Satranç tahtası", "Yerde kırmızı kareli bir tahta."], ["Şaşkın konuklar", "Toplantıya çağrılan konuklar."], ["Yemek hazırlığı", "Dışarıda kazanları ateşe koyan hizmetkârlar."], ["Farsça metin", "Yukarıda öykü Farsça yazılmış."]]}, "id": {"title": "Monyet yang terluka menggigit tangan pangeran, kawan caturnya (dari Tuti-nama, Kisah-Kisah Burung Nuri)", "artist": "Dasavanta", "date": "sekitar 1560", "place": "India (istana Mughal Akbar)", "game": "Catur", "medium": "Tempera, tinta, dan emas di atas kertas", "size": "20 × 14,2 cm (lukisan 10,2 × 10,6 cm)", "credit": "Hadiah Ny. A. Dean Perry, 1962", "p": ["Ilustrasi dari Tuti-nama, “Kisah-Kisah Burung Nuri”, yang dibuat di istana Kaisar Mughal Akbar. Ini salah satu cerita yang dituturkan induk nuri kepada anak-anaknya agar mereka tidak bersahabat dengan jenis makhluk lain, seperti anak-anak rubah. Dalam cerita itu, seekor monyet yang pandai bermain catur sering bermain dengan seorang pangeran.", "Suatu hari, di depan para tamu, si monyet melontarkan lelucon kasar; pangeran menamparnya, dan monyet itu menggigit tangan pangeran. Di luar sebelah kanan, para pelayan menyiapkan makanan sementara para tamu menonton dengan tercengang. Tulisan di bawah menyebut nama Dasavanta, yang kelak menjadi salah satu empu paling termasyhur di istana Mughal; semasa muda ia melapisi bagian bawah lukisannya dengan warna biru yang sejuk."], "spots": [["Si monyet", "Menggigit tangan pangeran, kawan caturnya."], ["Sang pangeran", "Pangeran yang tangannya digigit."], ["Papan catur", "Papan berpetak merah di lantai."], ["Para tamu yang tercengang", "Para tamu yang diundang."], ["Menyiapkan makanan", "Di luar, pelayan menaruh periuk di atas api."], ["Teks Persia", "Di atas, kisahnya ditulis dalam bahasa Persia."]]}, "hi": {"title": "घायल बंदर अपने शतरंज‑साथी राजकुमार का हाथ काटता है (“तूती‑नामा”, तोते की कहानियाँ से)", "artist": "दसवंत", "date": "लगभग 1560", "place": "भारत (अकबर का मुग़ल दरबार)", "game": "शतरंज", "medium": "काग़ज़ पर गोंद‑टेम्पेरा, स्याही और सोना", "size": "20 × 14.2 सेमी (चित्र 10.2 × 10.6 सेमी)", "credit": "श्रीमती ए. डीन पेरी का उपहार, 1962", "p": ["यह मुग़ल बादशाह अकबर के दरबार में बनी “तूती‑नामा” (तोते की कहानियाँ) का एक चित्र है। यह उन कहानियों में से एक है जो माँ‑तोती अपने बच्चों को लोमड़ी के बच्चों जैसे दूसरी जाति के जीवों से दोस्ती न करने की सीख देने के लिए सुनाती है। इसमें शतरंज में माहिर एक बंदर अक्सर एक राजकुमार के साथ खेलता था।", "एक दिन मेहमानों के सामने बंदर ने भद्दा मज़ाक किया, राजकुमार ने उसे थप्पड़ मारा, और बंदर ने राजकुमार का हाथ काट लिया। दाईं ओर बाहर नौकर खाना बना रहे हैं और मेहमान हैरानी से देख रहे हैं। नीचे के लेख में दसवंत का नाम है, जो आगे चलकर मुग़ल दरबार के सबसे प्रसिद्ध उस्तादों में से एक बने; युवा दसवंत ने चित्र के नीचे ठंडे नीले रंग की एक परत लगाई थी।"], "spots": [["बंदर", "अपने शतरंज‑साथी राजकुमार का हाथ काटता बंदर।"], ["राजकुमार", "जिस राजकुमार का हाथ काटा गया।"], ["शतरंज की बिसात", "फ़र्श पर रखी लाल ख़ानों वाली बिसात।"], ["हैरान मेहमान", "दावत में बुलाए गए मेहमान।"], ["खाने की तैयारी", "बाहर आग पर देगें चढ़ाते नौकर।"], ["फ़ारसी पाठ", "ऊपर कहानी फ़ारसी में लिखी है।"]]}, "ar": {"title": "القرد الجريح يعضّ يد الأمير رفيقه في الشطرنج (من «طوطي نامه»، حكايات الببغاء)", "artist": "داساوانتا", "date": "نحو 1560", "place": "الهند (بلاط أكبر المغولي)", "game": "الشطرنج", "medium": "ألوان صمغية وحبر وذهب على ورق", "size": "20 × 14.2 سم (الصورة 10.2 × 10.6 سم)", "credit": "هدية السيدة أ. دين بيري، 1962", "p": ["صورة من «طوطي نامه» أي «حكايات الببغاء»، صُنعت في بلاط الإمبراطور المغولي أكبر. وهي إحدى الحكايات التي ترويها أم الببغاوات لصغارها لتحذّرهم من مصادقة أنواع أخرى من المخلوقات، مثل صغار الثعالب. وفيها قرد بارع في الشطرنج كان يلاعب أميرًا كثيرًا.", "وذات يوم، أمام الضيوف، أطلق القرد مزحة فظة فصفعه الأمير، فعضّ القرد يد الأمير. وفي الخارج إلى اليمين يعدّ الخدم الطعام والضيوف ينظرون مذهولين. ويذكر نقش في الأسفل اسم داساوانتا الذي صار لاحقًا من أشهر أساتذة البلاط المغولي، وقد وضع وهو شاب طبقة من الأزرق البارد تحت صورته."], "spots": [["القرد", "يعضّ يد الأمير رفيقه في الشطرنج."], ["الأمير", "الأمير الذي عُضّت يده."], ["رقعة الشطرنج", "رقعة بمربعات حمراء على الأرض."], ["الضيوف المذهولون", "الضيوف المدعوون إلى المجلس."], ["إعداد الطعام", "في الخارج يضع الخدم القدور على النار."], ["النص الفارسي", "في الأعلى كُتبت الحكاية بالفارسية."]]}}, "teniers": {"ja": {"title": "バックギャモンの勝負", "artist": "ダーフィット・テニールス", "date": "1640年代", "place": "フランドル", "game": "バックギャモン", "medium": "油彩、板から画布に移し替え", "size": "59×80.6cm", "credit": "サミュエル・D・ワイズ夫妻寄贈、1943年", "p": ["フランドルの画家テニールスが描いた、賭けのかかったバックギャモンの大勝負です。バックギャモンの歴史は長く、いまの形は1400年代に現れ、「バックギャモン」という名前はちょうどこの絵のころに生まれたといいます。1600年代にはとても流行し、お金を賭けてよく遊ばれました。", "2人の対局者のまわりには見物人がいて、壁ぎわでは点数をつけている人もいます。窓から見下ろす女性などから、美術館はここを娼館の遊技部屋とみています。こうした遊びの場面は、賭けごとは愚かで悪いこと、時間のむだだという教えを込めて描かれることがよくありました。"], "spots": [["盤", "開いたバックギャモン盤。手前のテーブルの上で勝負が進んでいます。"], ["白いシャツの男", "背中を見せる対局者。駒に手をのばしています。"], ["頬づえの男", "向かいの対局者。頬に手を当てて考えこんでいます。"], ["点数をつける人", "壁ぎわで板に印をつけている男。点数か賭け金の記録でしょうか。"], ["窓の女性", "窓から勝負をのぞく年配の女性。"], ["奥の部屋", "奥では女性のそばで男たちが飲んでいます。"]]}, "en": {"title": "Game of Backgammon", "artist": "David Teniers", "date": "1640s", "place": "Flanders", "game": "Backgammon", "medium": "Oil on wood, transferred to canvas", "size": "59 × 80.6 cm", "credit": "Gift of Mr. and Mrs. Samuel D. Wise, 1943", "p": ["A high-stakes game of backgammon by the Flemish painter Teniers. Backgammon is very old; its modern form appeared in the 1400s, and the name “backgammon” was coined at about the time this picture was painted. In the 1600s the game was hugely popular and often played for money.", "Onlookers crowd around the two players, and against the wall someone keeps score. From the women watching — one leans from a window — the museum takes the room to be a gaming room in a brothel. Scenes of play like this often carried a moral: gambling was foolish, even wicked, and a waste of time."], "spots": [["The board", "An open backgammon board on the table, the game under way."], ["The man in white", "A player seen from behind, reaching for his men."], ["The man with his chin in his hand", "The opponent, deep in thought."], ["Keeping score", "A man marking a board on the wall — the score, or the stakes?"], ["The woman at the window", "An older woman watching from above."], ["The back room", "Men drink beside a young woman in the room beyond."]]}, "zh": {"title": "双陆对局", "artist": "大卫·特尼尔斯", "date": "17世纪40年代", "place": "佛兰德", "game": "西洋双陆", "medium": "木板油画，后转移到画布", "size": "59×80.6厘米", "credit": "塞缪尔·D·怀斯夫妇捐赠，1943年", "p": ["佛兰德画家特尼尔斯画的一场押了重注的西洋双陆大战。这种游戏历史悠久，现代形式出现于15世纪，而“backgammon”这个名字大约就诞生在这幅画的年代。17世纪它非常流行，常常用来赌钱。", "两位对手周围挤满看客，墙边还有人在记分。从窗口探头的女人等细节看，美术馆认为这里是妓院里的赌博间。这类游戏场景常带着训诫：赌博愚蠢、甚至邪恶，而且浪费时间。"], "spots": [["棋盘", "桌上打开的双陆棋盘，对局正在进行。"], ["白衬衫的男人", "背对我们的棋手，正伸手去拿棋子。"], ["托腮的男人", "对面的棋手，托着腮陷入沉思。"], ["记分的人", "在墙上的板子上做记号的男人——记的是分数还是赌注？"], ["窗口的女人", "从窗口往下看的年长女人。"], ["里屋", "里屋的男人们在一位年轻女子身旁喝酒。"]]}, "zh-TW": {"title": "雙陸對局", "artist": "大衛·特尼爾斯", "date": "1640年代", "place": "法蘭德斯", "game": "西洋雙陸", "medium": "木板油畫，後轉移到畫布", "size": "59×80.6公分", "credit": "塞繆爾·D·懷斯夫婦捐贈，1943年", "p": ["法蘭德斯畫家特尼爾斯畫的一場押了重注的西洋雙陸大戰。這種遊戲歷史悠久，現代形式出現於15世紀，而「backgammon」這個名字大約就誕生在這幅畫的年代。17世紀它非常流行，常常用來賭錢。", "兩位對手周圍擠滿看客，牆邊還有人在記分。從窗口探頭的女人等細節看，美術館認為這裡是妓院裡的賭博間。這類遊戲場景常帶著訓誡：賭博愚蠢、甚至邪惡，而且浪費時間。"], "spots": [["棋盤", "桌上打開的雙陸棋盤，對局正在進行。"], ["白襯衫的男人", "背對我們的棋手，正伸手去拿棋子。"], ["托腮的男人", "對面的棋手，托著腮陷入沉思。"], ["記分的人", "在牆上的板子上做記號的男人——記的是分數還是賭注？"], ["窗口的女人", "從窗口往下看的年長女人。"], ["裡屋", "裡屋的男人們在一位年輕女子身旁喝酒。"]]}, "ko": {"title": "백개먼 승부", "artist": "다비트 테니르스", "date": "1640년대", "place": "플랑드르", "game": "백개먼", "medium": "나무판에 유채, 캔버스로 옮김", "size": "59×80.6cm", "credit": "새뮤얼 D. 와이즈 부부 기증, 1943년", "p": ["플랑드르 화가 테니르스가 그린, 큰돈이 걸린 백개먼 승부입니다. 백개먼은 역사가 길어 지금의 형태는 1400년대에 나타났고, ‘백개먼’이라는 이름은 바로 이 그림 무렵에 생겼다고 합니다. 1600년대에 크게 유행해 돈을 걸고 자주 했습니다.", "두 대국자 둘레에 구경꾼이 모여 있고, 벽 쪽에서는 점수를 적는 사람도 있습니다. 창문으로 내다보는 여인 등을 근거로 미술관은 이곳을 유곽의 놀이방으로 봅니다. 이런 놀이 장면에는 도박은 어리석고 나쁜 일이며 시간 낭비라는 교훈이 담기곤 했습니다."], "spots": [["판", "탁자 위에 펼친 백개먼 판. 승부가 진행 중입니다."], ["흰 셔츠의 남자", "등을 보인 대국자. 말에 손을 뻗고 있습니다."], ["턱을 괸 남자", "맞은편 대국자. 턱을 괴고 생각에 잠겨 있습니다."], ["점수 적는 사람", "벽의 판에 표시를 하는 남자. 점수일까, 판돈일까?"], ["창가의 여인", "창에서 승부를 내려다보는 나이 든 여인."], ["안쪽 방", "안쪽 방에서는 젊은 여인 곁에서 남자들이 술을 마십니다."]]}, "es": {"title": "Partida de backgammon", "artist": "David Teniers", "date": "década de 1640", "place": "Flandes", "game": "Backgammon", "medium": "Óleo sobre tabla, pasado a lienzo", "size": "59 × 80,6 cm", "credit": "Donación del Sr. y la Sra. Samuel D. Wise, 1943", "p": ["Una partida de backgammon con mucho en juego, pintada por el flamenco Teniers. El juego es muy antiguo: su forma moderna apareció en el siglo XV, y el nombre «backgammon» nació más o menos cuando se pintó este cuadro. En el siglo XVII era popularísimo y se jugaba a menudo por dinero.", "Los mirones rodean a los dos jugadores, y junto a la pared alguien lleva la cuenta. Por las mujeres que miran —una se asoma a una ventana— el museo cree que la sala es el cuarto de juego de un burdel. Estas escenas solían llevar una moraleja: el juego de azar era necio, incluso perverso, y una pérdida de tiempo."], "spots": [["El tablero", "Un tablero de backgammon abierto sobre la mesa, con la partida en marcha."], ["El hombre de blanco", "Un jugador de espaldas, alargando la mano hacia sus fichas."], ["El hombre con la mano en la mejilla", "Su rival, absorto."], ["El tanteador", "Un hombre marca una tabla en la pared: ¿los puntos o las apuestas?"], ["La mujer en la ventana", "Una mujer mayor que mira desde arriba."], ["La sala del fondo", "Al fondo, hombres beben junto a una joven."]]}, "fr": {"title": "Partie de trictrac", "artist": "David Teniers", "date": "années 1640", "place": "Flandres", "game": "Backgammon", "medium": "Huile sur bois, transposée sur toile", "size": "59 × 80,6 cm", "credit": "Don de M. et Mme Samuel D. Wise, 1943", "p": ["Une partie de backgammon à gros enjeu, peinte par le Flamand Teniers. Le jeu est très ancien : sa forme moderne apparaît au XVe siècle, et le nom « backgammon » naît à peu près à l’époque de ce tableau. Au XVIIe siècle, il était très en vogue et se jouait souvent pour de l’argent.", "Des badauds entourent les deux joueurs, et contre le mur quelqu’un tient la marque. D’après les femmes qui regardent — l’une se penche à une fenêtre —, le musée voit ici la salle de jeu d’une maison close. Ces scènes de jeu portaient souvent une morale : le jeu d’argent était sot, voire coupable, et une perte de temps."], "spots": [["Le tablier", "Un tablier de backgammon ouvert sur la table, la partie en cours."], ["L’homme en blanc", "Un joueur vu de dos, qui avance la main vers ses dames."], ["L’homme pensif", "Son adversaire, la joue dans la main."], ["La marque", "Un homme marque une planchette au mur : les points, ou les mises ?"], ["La femme à la fenêtre", "Une femme âgée qui regarde d’en haut."], ["L’arrière-salle", "Au fond, des hommes boivent près d’une jeune femme."]]}, "pt": {"title": "Partida de gamão", "artist": "David Teniers", "date": "década de 1640", "place": "Flandres", "game": "Gamão", "medium": "Óleo sobre madeira, transposto para tela", "size": "59 × 80,6 cm", "credit": "Doação do Sr. e da Sra. Samuel D. Wise, 1943", "p": ["Uma partida de gamão de apostas altas, pintada pelo flamengo Teniers. O jogo é antiquíssimo: sua forma moderna surgiu no século XV, e o nome «backgammon» nasceu mais ou menos na época deste quadro. No século XVII era muito popular e jogado com frequência a dinheiro.", "Curiosos cercam os dois jogadores, e junto à parede alguém marca os pontos. Pelas mulheres que observam — uma se debruça numa janela —, o museu entende que a sala é o salão de jogos de um bordel. Cenas de jogo assim muitas vezes traziam uma moral: o jogo a dinheiro era tolo, até perverso, e perda de tempo."], "spots": [["O tabuleiro", "Um tabuleiro de gamão aberto sobre a mesa, a partida em andamento."], ["O homem de branco", "Um jogador de costas, estendendo a mão às pedras."], ["O homem pensativo", "O adversário, com a mão no rosto."], ["O marcador", "Um homem marca uma tábua na parede: os pontos ou as apostas?"], ["A mulher à janela", "Uma senhora que olha lá de cima."], ["A sala dos fundos", "Ao fundo, homens bebem ao lado de uma jovem."]]}, "de": {"title": "Die Backgammonpartie", "artist": "David Teniers", "date": "1640er Jahre", "place": "Flandern", "game": "Backgammon", "medium": "Öl auf Holz, auf Leinwand übertragen", "size": "59 × 80,6 cm", "credit": "Schenkung von Mr. und Mrs. Samuel D. Wise, 1943", "p": ["Eine Backgammonpartie um hohe Einsätze, gemalt vom Flamen Teniers. Das Spiel ist sehr alt: Seine heutige Form entstand im 15. Jahrhundert, und der Name „Backgammon“ kam etwa zur Zeit dieses Bildes auf. Im 17. Jahrhundert war es äußerst beliebt und wurde oft um Geld gespielt.", "Zuschauer drängen sich um die beiden Spieler, und an der Wand führt jemand Buch. Wegen der zuschauenden Frauen – eine lehnt aus einem Fenster – hält das Museum den Raum für das Spielzimmer eines Bordells. Solche Spielszenen trugen oft eine Moral: Glücksspiel sei töricht, ja verwerflich, und Zeitverschwendung."], "spots": [["Das Brett", "Ein aufgeklapptes Backgammonbrett auf dem Tisch, die Partie läuft."], ["Der Mann in Weiß", "Ein Spieler von hinten, der nach seinen Steinen greift."], ["Der Grübler", "Sein Gegner, die Wange in die Hand gestützt."], ["Der Anschreiber", "Ein Mann markiert eine Tafel an der Wand – Punkte oder Einsätze?"], ["Die Frau am Fenster", "Eine ältere Frau schaut von oben zu."], ["Das Hinterzimmer", "Hinten trinken Männer neben einer jungen Frau."]]}, "ru": {"title": "Игра в нарды", "artist": "Давид Тенирс", "date": "1640-е годы", "place": "Фландрия", "game": "Нарды (бэкгаммон)", "medium": "Масло, дерево, переведено на холст", "size": "59 × 80,6 см", "credit": "Дар мистера и миссис Сэмюэл Д. Уайз, 1943", "p": ["Партия в нарды на большую ставку кисти фламандца Тенирса. Игра очень древняя: её современная форма появилась в XV веке, а название «бэкгаммон» возникло примерно тогда, когда была написана эта картина. В XVII веке игра была чрезвычайно популярна, и в неё часто играли на деньги.", "Зеваки окружают двух игроков, а у стены кто-то ведёт счёт. По женщинам, которые смотрят на игру, — одна выглядывает из окна — музей считает эту комнату игорной в доме терпимости. Такие сцены игры часто несли мораль: азартная игра глупа, даже порочна и лишь крадёт время."], "spots": [["Доска", "Раскрытая доска для нард на столе, партия идёт."], ["Человек в белом", "Игрок спиной к нам тянется к шашкам."], ["Задумчивый", "Его соперник, подперев щёку рукой."], ["Счёт", "Человек делает отметки на доске у стены — очки или ставки?"], ["Женщина в окне", "Пожилая женщина смотрит сверху."], ["Задняя комната", "В глубине мужчины пьют возле молодой женщины."]]}, "tr": {"title": "Tavla oyunu", "artist": "David Teniers", "date": "1640’lar", "place": "Flandre", "game": "Tavla (backgammon)", "medium": "Ahşap üzerine yağlıboya, tuvale aktarılmış", "size": "59 × 80,6 cm", "credit": "Bay ve Bayan Samuel D. Wise bağışı, 1943", "p": ["Flaman ressam Teniers’in yüksek bahisli bir tavla maçını gösteren tablosu. Oyun çok eskidir: bugünkü biçimi 1400’lerde ortaya çıktı, “backgammon” adı da aşağı yukarı bu resmin yapıldığı sıralarda doğdu. 1600’lerde çok yaygındı ve sık sık para için oynanırdı.", "İki oyuncunun çevresini seyirciler sarmış, duvar dibinde de biri puan tutuyor. Seyreden kadınlardan — biri pencereden sarkıyor — yola çıkan müze, odanın bir genelevin oyun odası olduğunu düşünüyor. Böyle oyun sahneleri çoğu zaman bir ders taşırdı: kumar aptalca, hatta kötüdür ve vakit kaybıdır."], "spots": [["Tahta", "Masada açık bir tavla tahtası; oyun sürüyor."], ["Beyazlı adam", "Sırtı dönük oyuncu, pullarına uzanıyor."], ["Düşünceli adam", "Rakibi, elini yanağına dayamış."], ["Puan tutan", "Duvardaki tahtaya işaret koyan adam — puan mı, bahis mi?"], ["Penceredeki kadın", "Yukarıdan bakan yaşlı bir kadın."], ["Arka oda", "Arkada erkekler genç bir kadının yanında içiyor."]]}, "id": {"title": "Permainan backgammon", "artist": "David Teniers", "date": "1640-an", "place": "Flandria", "game": "Backgammon", "medium": "Cat minyak di atas kayu, dipindahkan ke kanvas", "size": "59 × 80,6 cm", "credit": "Hadiah Tn. dan Ny. Samuel D. Wise, 1943", "p": ["Pertandingan backgammon bertaruhan besar karya pelukis Flandria, Teniers. Permainan ini sangat tua: bentuk modernnya muncul pada 1400-an, dan nama “backgammon” lahir kira-kira pada masa lukisan ini dibuat. Pada 1600-an ia sangat populer dan sering dimainkan dengan taruhan uang.", "Para penonton mengerumuni kedua pemain, dan di dekat dinding seseorang mencatat skor. Dari para perempuan yang menonton — salah satunya menjulurkan kepala dari jendela — museum menduga ruangan ini adalah ruang judi di sebuah rumah bordil. Adegan permainan seperti ini kerap membawa pesan moral: berjudi itu bodoh, bahkan jahat, dan membuang waktu."], "spots": [["Papan", "Papan backgammon yang terbuka di atas meja; permainan sedang berlangsung."], ["Pria berbaju putih", "Pemain yang membelakangi kita, menjangkau bidaknya."], ["Pria bertopang dagu", "Lawannya, termenung."], ["Pencatat skor", "Seorang pria menandai papan di dinding — skor, atau taruhan?"], ["Perempuan di jendela", "Seorang perempuan tua menonton dari atas."], ["Ruang belakang", "Di belakang, para pria minum di dekat seorang perempuan muda."]]}, "hi": {"title": "बैकगैमन की बाज़ी", "artist": "डेविड टेनियर्स", "date": "1640 का दशक", "place": "फ़्लैंडर्स", "game": "बैकगैमन", "medium": "लकड़ी पर तैलचित्र, कैनवस पर स्थानांतरित", "size": "59 × 80.6 सेमी", "credit": "श्री और श्रीमती सैमुअल डी. वाइज़ का उपहार, 1943", "p": ["फ़्लेमिश चित्रकार टेनियर्स का यह चित्र बड़े दाँव वाली बैकगैमन की बाज़ी दिखाता है। यह खेल बहुत पुराना है: इसका आधुनिक रूप 1400 के दशक में आया, और “बैकगैमन” नाम लगभग इसी चित्र के समय पड़ा। 1600 के दशक में यह बेहद लोकप्रिय था और अक्सर पैसों के लिए खेला जाता था।", "दोनों खिलाड़ियों को दर्शक घेरे हुए हैं, और दीवार के पास कोई अंक लिख रहा है। देखती हुई स्त्रियों से — एक खिड़की से झाँक रही है — संग्रहालय मानता है कि यह किसी वेश्यालय का जुआघर है। ऐसे खेल‑दृश्यों में अक्सर नैतिक सीख होती थी: जुआ मूर्खता है, बुराई भी, और समय की बर्बादी।"], "spots": [["बिसात", "मेज़ पर खुली बैकगैमन की बिसात; बाज़ी चल रही है।"], ["सफ़ेद कमीज़ वाला", "पीठ किए खिलाड़ी, अपनी गोटियों की ओर हाथ बढ़ाता।"], ["गाल पर हाथ रखे", "सामने वाला खिलाड़ी, सोच में डूबा।"], ["अंक लिखने वाला", "दीवार की पट्टी पर निशान लगाता आदमी — अंक या दाँव?"], ["खिड़की की स्त्री", "ऊपर से झाँकती एक बुज़ुर्ग स्त्री।"], ["पीछे का कमरा", "पीछे एक युवती के पास आदमी शराब पी रहे हैं।"]]}, "ar": {"title": "دور في النرد (الطاولة)", "artist": "دافيد تينيرز", "date": "أربعينيات القرن السابع عشر", "place": "الفلاندر", "game": "الطاولة (الباكغامون)", "medium": "زيت على خشب، نُقل إلى قماش", "size": "59 × 80.6 سم", "credit": "هدية السيد والسيدة صموئيل د. وايز، 1943", "p": ["دور في الطاولة على رهان كبير رسمه الفلمنكي تينيرز. واللعبة قديمة جدًا: ظهرت صورتها الحديثة في القرن الخامس عشر، ووُلد اسم «باكغامون» نحو زمن هذه اللوحة. وكانت في القرن السابع عشر شائعة جدًا، وكثيرًا ما لُعبت على المال.", "يحيط المتفرجون باللاعبين، وعند الجدار رجل يسجّل النقاط. ومن النساء اللواتي يتفرجن — وإحداهن تطل من نافذة — يرى المتحف أن الغرفة قاعة قمار في ماخور. وكثيرًا ما حملت مشاهد اللعب هذه موعظة: القمار حماقة، بل شر، ومضيعة للوقت."], "spots": [["اللوح", "لوح طاولة مفتوح على المنضدة، والدور جارٍ."], ["الرجل ذو القميص الأبيض", "لاعب يُدير ظهره ويمد يده إلى قطعه."], ["الرجل المتأمل", "خصمه، يسند خده إلى يده."], ["مسجّل النقاط", "رجل يعلّم لوحًا على الجدار: النقاط أم الرهان؟"], ["المرأة في النافذة", "امرأة مسنّة تنظر من الأعلى."], ["الغرفة الخلفية", "في الخلف يشرب رجال قرب امرأة شابة."]]}}, "imari": {"ja": {"title": "碁を打つ2人の角皿", "artist": "作者不明", "date": "1700年代", "place": "日本（江戸時代）", "game": "囲碁", "medium": "磁器、型打ち、上絵付（肥前、伊万里様式）", "size": "2.4×13.8cm", "credit": "セヴェランス・アンド・グレタ・ミリキン・コレクション、1964年", "p": ["手のひらにのる小さな角皿に、松の木の下で碁を打つ2人が描かれています。地面にじかに置いた盤を、黄色い衣の人と、木にもたれた緑の衣の人がはさんでいます。", "肥前（いまの佐賀・長崎）で焼かれた伊万里の磁器で、緑の色づかいは九谷の色絵に通じるといいます。日本が中国に代わってヨーロッパへの輸出磁器のおもな作り手になったころ、輸出向けに作られた品です。"], "spots": [["碁盤", "升目を描いた碁盤。地面に直接置かれています。"], ["黄色い衣の人", "盤に向かって座る人。"], ["緑の衣の人", "木にもたれて笑う相手。"], ["松", "頭上に枝をのばす松。"], ["赤い枠", "角を切った赤い枠が絵を囲みます。"]]}, "en": {"title": "Dish with two men playing go", "artist": "Unknown", "date": "1700s", "place": "Japan (Edo period)", "game": "Go", "medium": "Porcelain, molded, with overglaze enamel (Hizen ware, Imari style)", "size": "2.4 × 13.8 cm", "credit": "Severance and Greta Millikin Collection, 1964", "p": ["On this small square dish, two men play go under a pine tree: one in yellow sits facing the board, set straight on the ground, while his opponent in green leans back against the tree.", "It is Imari porcelain from Hizen (today’s Saga and Nagasaki), and its greens recall Kutani enamels. It was made for export, after Japan had replaced China as Europe’s main supplier of porcelain."], "spots": [["The go board", "A board ruled in squares, set straight on the ground."], ["The man in yellow", "Seated, facing the board."], ["The man in green", "His opponent, leaning back against the tree and smiling."], ["The pine", "A pine stretches its branches overhead."], ["The red frame", "A red frame with cut corners surrounds the picture."]]}, "zh": {"title": "下围棋的两人方盘", "artist": "佚名", "date": "18世纪", "place": "日本（江户时代）", "game": "围棋", "medium": "瓷器，模制，釉上彩（肥前窑，伊万里风格）", "size": "2.4×13.8厘米", "credit": "塞弗伦斯与格丽塔·米利金收藏，1964年", "p": ["这只小小的方盘上，两人在松树下下围棋：穿黄衣的人对着直接放在地上的棋盘坐着，穿绿衣的对手靠在树上。", "这是肥前（今佐贺、长崎）烧制的伊万里瓷器，绿色的用法让人想起九谷彩绘。它是为外销而做的——当时日本已取代中国，成为欧洲瓷器的主要供应者。"], "spots": [["棋盘", "画着格子的围棋盘，直接放在地上。"], ["黄衣人", "面向棋盘坐着的人。"], ["绿衣人", "靠在树上微笑的对手。"], ["松树", "在头顶伸展枝条的松树。"], ["红框", "切去四角的红框围住画面。"]]}, "zh-TW": {"title": "下圍棋的兩人方盤", "artist": "佚名", "date": "18世紀", "place": "日本（江戶時代）", "game": "圍棋", "medium": "瓷器，模製，釉上彩（肥前窯，伊萬里風格）", "size": "2.4×13.8公分", "credit": "塞弗倫斯與葛麗塔·米利金收藏，1964年", "p": ["這只小小的方盤上，兩人在松樹下下圍棋：穿黃衣的人對著直接放在地上的棋盤坐著，穿綠衣的對手靠在樹上。", "這是肥前（今佐賀、長崎）燒製的伊萬里瓷器，綠色的用法讓人想起九谷彩繪。它是為外銷而做的——當時日本已取代中國，成為歐洲瓷器的主要供應者。"], "spots": [["棋盤", "畫著格子的圍棋盤，直接放在地上。"], ["黃衣人", "面向棋盤坐著的人。"], ["綠衣人", "靠在樹上微笑的對手。"], ["松樹", "在頭頂伸展枝條的松樹。"], ["紅框", "切去四角的紅框圍住畫面。"]]}, "ko": {"title": "바둑 두는 두 사람의 각접시", "artist": "작자 미상", "date": "1700년대", "place": "일본(에도 시대)", "game": "바둑", "medium": "자기, 틀 성형, 상회(히젠, 이마리 양식)", "size": "2.4×13.8cm", "credit": "세버런스 앤드 그레타 밀리킨 컬렉션, 1964년", "p": ["손바닥만 한 각접시에 소나무 아래서 바둑을 두는 두 사람이 그려져 있습니다. 노란 옷의 사람은 땅에 바로 놓은 판을 마주하고 앉았고, 초록 옷의 상대는 나무에 기대어 있습니다.", "히젠(지금의 사가·나가사키)에서 구운 이마리 자기로, 초록 색감은 구타니 색회를 떠올리게 한다고 합니다. 일본이 중국을 대신해 유럽 수출 자기의 주된 공급처가 되었을 무렵 수출용으로 만든 물건입니다."], "spots": [["바둑판", "칸을 그린 바둑판. 땅에 바로 놓여 있습니다."], ["노란 옷의 사람", "판을 마주하고 앉은 사람."], ["초록 옷의 사람", "나무에 기대어 웃는 상대."], ["소나무", "머리 위로 가지를 뻗은 소나무."], ["빨간 테두리", "모서리를 자른 빨간 테두리가 그림을 두릅니다."]]}, "es": {"title": "Plato con dos hombres jugando al go", "artist": "Anónimo", "date": "siglo XVIII", "place": "Japón (periodo Edo)", "game": "Go", "medium": "Porcelana moldeada con esmaltes sobre cubierta (Hizen, estilo Imari)", "size": "2,4 × 13,8 cm", "credit": "Colección Severance y Greta Millikin, 1964", "p": ["En este pequeño plato cuadrado, dos hombres juegan al go bajo un pino: el de amarillo, sentado frente al tablero puesto en el suelo; su rival de verde, recostado en el árbol.", "Es porcelana de Imari hecha en Hizen (hoy Saga y Nagasaki), y sus verdes recuerdan los esmaltes de Kutani. Se hizo para la exportación, cuando Japón ya había sustituido a China como principal proveedor de porcelana de Europa."], "spots": [["El tablero de go", "Un tablero cuadriculado, puesto directamente en el suelo."], ["El hombre de amarillo", "Sentado frente al tablero."], ["El hombre de verde", "Su rival, recostado en el árbol y sonriendo."], ["El pino", "Un pino extiende sus ramas por encima."], ["El marco rojo", "Un marco rojo de esquinas cortadas rodea la escena."]]}, "fr": {"title": "Plat à deux joueurs de go", "artist": "Anonyme", "date": "XVIIIe siècle", "place": "Japon (époque d’Edo)", "game": "Go", "medium": "Porcelaine moulée, émaux sur couverte (Hizen, style Imari)", "size": "2,4 × 13,8 cm", "credit": "Collection Severance et Greta Millikin, 1964", "p": ["Sur ce petit plat carré, deux hommes jouent au go sous un pin : l’un, en jaune, assis face au goban posé à même le sol ; son adversaire, en vert, adossé à l’arbre.", "C’est une porcelaine d’Imari faite dans le Hizen (aujourd’hui Saga et Nagasaki), dont les verts rappellent les émaux de Kutani. Elle fut faite pour l’exportation, quand le Japon avait remplacé la Chine comme principal fournisseur de porcelaine de l’Europe."], "spots": [["Le goban", "Un plateau quadrillé posé à même le sol."], ["L’homme en jaune", "Assis face au plateau."], ["L’homme en vert", "Son adversaire, adossé à l’arbre, souriant."], ["Le pin", "Un pin étend ses branches au-dessus d’eux."], ["Le cadre rouge", "Un cadre rouge à pans coupés entoure la scène."]]}, "pt": {"title": "Prato com dois homens jogando go", "artist": "Autor desconhecido", "date": "século XVIII", "place": "Japão (período Edo)", "game": "Go", "medium": "Porcelana moldada, esmaltes sobre o vidrado (Hizen, estilo Imari)", "size": "2,4 × 13,8 cm", "credit": "Coleção Severance e Greta Millikin, 1964", "p": ["Neste pequeno prato quadrado, dois homens jogam go sob um pinheiro: o de amarelo, sentado diante do tabuleiro posto no chão; o adversário de verde, encostado na árvore.", "É porcelana de Imari feita em Hizen (hoje Saga e Nagasaki), e seus verdes lembram os esmaltes de Kutani. Foi feito para exportação, quando o Japão já substituíra a China como principal fornecedor de porcelana da Europa."], "spots": [["O tabuleiro de go", "Um tabuleiro quadriculado, posto direto no chão."], ["O homem de amarelo", "Sentado diante do tabuleiro."], ["O homem de verde", "O adversário, encostado na árvore e sorrindo."], ["O pinheiro", "Um pinheiro estende os galhos por cima."], ["A moldura vermelha", "Uma moldura vermelha de cantos cortados envolve a cena."]]}, "de": {"title": "Schale mit zwei Go-Spielern", "artist": "Unbekannt", "date": "18. Jahrhundert", "place": "Japan (Edo-Zeit)", "game": "Go", "medium": "Porzellan, geformt, mit Aufglasurfarben (Hizen, Imari-Stil)", "size": "2,4 × 13,8 cm", "credit": "Severance and Greta Millikin Collection, 1964", "p": ["Auf dieser kleinen quadratischen Schale spielen zwei Männer unter einer Kiefer Go: der eine in Gelb sitzt vor dem Brett, das direkt auf dem Boden liegt; sein Gegner in Grün lehnt am Baum.", "Es ist Imari-Porzellan aus Hizen (heute Saga und Nagasaki); seine Grüntöne erinnern an Kutani-Emails. Gefertigt wurde es für den Export, als Japan China als wichtigsten Porzellanlieferanten Europas abgelöst hatte."], "spots": [["Das Go-Brett", "Ein gerastertes Brett, direkt auf dem Boden."], ["Der Mann in Gelb", "Er sitzt vor dem Brett."], ["Der Mann in Grün", "Sein Gegner, lächelnd an den Baum gelehnt."], ["Die Kiefer", "Eine Kiefer breitet ihre Zweige über ihnen aus."], ["Der rote Rahmen", "Ein roter Rahmen mit abgeschrägten Ecken umgibt die Szene."]]}, "ru": {"title": "Блюдо с двумя игроками в го", "artist": "Неизвестный мастер", "date": "XVIII век", "place": "Япония (период Эдо)", "game": "Го", "medium": "Фарфор, формовка, надглазурные эмали (Хидзэн, стиль Имари)", "size": "2,4 × 13,8 см", "credit": "Собрание Северанса и Греты Милликин, 1964", "p": ["На этом маленьком квадратном блюде двое играют в го под сосной: один, в жёлтом, сидит перед доской, положенной прямо на землю, а его соперник в зелёном прислонился к дереву.", "Это фарфор Имари из Хидзэна (ныне Сага и Нагасаки); его зелёные тона напоминают эмали Кутани. Блюдо сделано на экспорт, когда Япония уже сменила Китай в роли главного поставщика фарфора в Европу."], "spots": [["Доска для го", "Расчерченная доска прямо на земле."], ["Человек в жёлтом", "Сидит перед доской."], ["Человек в зелёном", "Соперник, улыбаясь, прислонился к дереву."], ["Сосна", "Сосна раскинула ветви над игроками."], ["Красная рамка", "Красная рамка со срезанными углами обрамляет сцену."]]}, "tr": {"title": "Go oynayan iki adamlı tabak", "artist": "Bilinmiyor", "date": "18. yüzyıl", "place": "Japonya (Edo dönemi)", "game": "Go", "medium": "Kalıpta biçimlendirilmiş porselen, sır üstü boya (Hizen, Imari üslubu)", "size": "2,4 × 13,8 cm", "credit": "Severance ve Greta Millikin Koleksiyonu, 1964", "p": ["Bu küçük kare tabakta iki adam bir çam ağacının altında go oynuyor: sarılı olan, doğrudan yere konmuş tahtanın karşısında oturuyor; yeşilli rakibi ağaca yaslanmış.", "Hizen’de (bugünkü Saga ve Nagasaki) yapılmış bir Imari porseleni; yeşilleri Kutani emayelerini andırıyor. Japonya’nın Avrupa’ya porselen tedarikinde Çin’in yerini aldığı dönemde ihracat için yapıldı."], "spots": [["Go tahtası", "Yere doğrudan konmuş, çizgili bir tahta."], ["Sarılı adam", "Tahtanın karşısında oturuyor."], ["Yeşilli adam", "Rakibi; gülümseyerek ağaca yaslanmış."], ["Çam", "Başlarının üstüne dallarını uzatan çam."], ["Kırmızı çerçeve", "Köşeleri kesik kırmızı bir çerçeve sahneyi kuşatıyor."]]}, "id": {"title": "Piring dengan dua pria bermain go", "artist": "Tidak diketahui", "date": "abad ke-18", "place": "Jepang (zaman Edo)", "game": "Go", "medium": "Porselen cetak dengan lukisan email di atas glasir (Hizen, gaya Imari)", "size": "2,4 × 13,8 cm", "credit": "Koleksi Severance dan Greta Millikin, 1964", "p": ["Di piring persegi kecil ini, dua pria bermain go di bawah pohon pinus: yang berbaju kuning duduk menghadap papan yang diletakkan langsung di tanah, sementara lawannya yang berbaju hijau bersandar ke pohon.", "Ini porselen Imari dari Hizen (kini Saga dan Nagasaki), dan warna hijaunya mengingatkan pada email Kutani. Piring ini dibuat untuk ekspor, ketika Jepang telah menggantikan Tiongkok sebagai pemasok utama porselen ke Eropa."], "spots": [["Papan go", "Papan bergaris yang diletakkan langsung di tanah."], ["Pria berbaju kuning", "Duduk menghadap papan."], ["Pria berbaju hijau", "Lawannya, bersandar ke pohon sambil tersenyum."], ["Pohon pinus", "Pinus yang menjulurkan dahannya di atas mereka."], ["Bingkai merah", "Bingkai merah bersudut potong mengelilingi adegan."]]}, "hi": {"title": "गो खेलते दो लोगों वाली तश्तरी", "artist": "अज्ञात", "date": "18वीं सदी", "place": "जापान (एदो काल)", "game": "गो", "medium": "ढाला हुआ चीनी‑मिट्टी का बर्तन, ग्लेज़ पर रंग (हिज़ेन, इमारी शैली)", "size": "2.4 × 13.8 सेमी", "credit": "सेवरेंस और ग्रेटा मिलिकिन संग्रह, 1964", "p": ["इस छोटी चौकोर तश्तरी पर चीड़ के पेड़ के नीचे दो लोग गो खेल रहे हैं: पीले वस्त्र वाला ज़मीन पर रखी बिसात के सामने बैठा है, और हरे वस्त्र वाला विरोधी पेड़ से टिका है।", "यह हिज़ेन (आज के सागा और नागासाकी) में बनी इमारी चीनी‑मिट्टी है, जिसके हरे रंग कुतानी के एनामेल की याद दिलाते हैं। इसे निर्यात के लिए बनाया गया था, जब जापान यूरोप को चीनी‑मिट्टी देने में चीन की जगह ले चुका था।"], "spots": [["गो की बिसात", "सीधे ज़मीन पर रखी, ख़ानों वाली बिसात।"], ["पीले वस्त्र वाला", "बिसात के सामने बैठा व्यक्ति।"], ["हरे वस्त्र वाला", "पेड़ से टिककर मुस्कुराता विरोधी।"], ["चीड़", "सिर के ऊपर शाखाएँ फैलाता चीड़।"], ["लाल चौखटा", "कटे कोनों वाला लाल चौखटा दृश्य को घेरे है।"]]}, "ar": {"title": "طبق عليه رجلان يلعبان الغو", "artist": "مجهول", "date": "القرن الثامن عشر", "place": "اليابان (عصر إدو)", "game": "الغو", "medium": "خزف مصبوب بألوان فوق الطلاء الزجاجي (هيزن، طراز إيماري)", "size": "2.4 × 13.8 سم", "credit": "مجموعة سيفيرانس وغريتا ميليكين، 1964", "p": ["على هذا الطبق المربع الصغير يلعب رجلان الغو تحت شجرة صنوبر: صاحب الثوب الأصفر يجلس قبالة اللوح الموضوع على الأرض مباشرة، وخصمه ذو الثوب الأخضر يستند إلى الشجرة.", "إنه خزف إيماري من هيزن (ساغا وناغاساكي اليوم)، وتذكّر خضرته بألوان كوتاني. وقد صُنع للتصدير، حين حلّت اليابان محل الصين موردًا رئيسيًا للخزف إلى أوروبا."], "spots": [["لوح الغو", "لوح مخطط موضوع على الأرض مباشرة."], ["صاحب الثوب الأصفر", "يجلس قبالة اللوح."], ["صاحب الثوب الأخضر", "خصمه، يستند إلى الشجرة مبتسمًا."], ["الصنوبر", "صنوبرة تمد أغصانها فوقهما."], ["الإطار الأحمر", "إطار أحمر مقطوع الزوايا يحيط بالمشهد."]]}}};
  Object.keys(A).forEach(id => Object.keys(A[id]).forEach(l => { if (T[l]) T[l][id] = A[id][l]; })); })(window.MUSEUM_PAINT_T);
