(T => { const A = {"shoei": {"ja": {"title": "琴棋書画図屛風（一隻）", "artist": "伝 狩野松栄", "date": "1500年代末〜1600年代初め", "place": "日本（桃山時代）", "game": "囲碁", "medium": "六曲一双のうち一隻、紙本墨画淡彩", "size": "153×358.6cm", "credit": "ジョン・L・セヴェランス基金、1979年", "p": ["狩野派の画家・狩野松栄の作と伝わる六曲屛風です。中国の文人が身につけるべきたしなみとされた「琴棋書画」——琴をひき、碁（棋）を打ち、書を書き、絵を描くこと——を、二隻一組で描いたうちの一隻。松の下の野原で、身分の高い中国の紳士たちが従者を連れてくつろいでいます。", "まん中では2人が碁を打ち、もう1人がそれを見守っています。そばの机には本と、布の袋に入ったままの琴が置かれ、ひかれるのを待っています。楽しみと礼儀正しさが釣り合った場面です。美術館の解説によれば、従者のひとりは水の中の魚の動きに気を取られているそうです。"], "spots": [["碁盤", "脚のついた碁盤。2人の紳士が向かい合って打っています。"], ["紳士たち", "碁を打つ2人と、それを見守るもう1人。"], ["机の上", "本と、袋に入ったままの琴が置かれた机と思われます。"], ["従者たち", "机のそばに控える従者。"], ["魚に気を取られる従者", "水辺に寝そべり、魚の動きを見ている従者。"], ["松", "画面の上に大きく枝を広げる松。"]]}, "en": {"title": "The Four Accomplishments (one of a pair of screens)", "artist": "attributed to Kano Shōei", "date": "late 1500s–early 1600s", "place": "Japan (Momoyama period)", "game": "Go", "medium": "One of a pair of six-panel folding screens; ink and slight color on paper", "size": "153 × 358.6 cm", "credit": "John L. Severance Fund, 1979", "p": ["A six-panel screen attributed to Kano Shōei of the Kano school. With its partner it shows the “Four Accomplishments” expected of a cultured Chinese gentleman — playing the qin, playing qi (go), calligraphy and painting. Here elite Chinese gentlemen and their servants relax in the countryside beneath the pines.", "At the centre two men play go while a third watches. Nearby a table holds books and a qin, still in its cloth case, waiting to be played. The scene balances enjoyment and formality. The museum points out that one of the servants is distracted by the movement of a fish in the water."], "spots": [["The go board", "A footed board; two gentlemen play across it."], ["The gentlemen", "Two players and a third who watches."], ["The table", "Probably the table with books and the qin still in its case."], ["The servants", "Attendants waiting by the table."], ["The distracted servant", "Lying by the water, watching a fish move."], ["The pine", "A great pine spreads its branches over the scene."]]}, "zh": {"title": "琴棋书画图屏风（一扇）", "artist": "传狩野松荣", "date": "16世纪末—17世纪初", "place": "日本（桃山时代）", "game": "围棋", "medium": "六曲一双之一，纸本墨画淡彩", "size": "153×358.6厘米", "credit": "约翰·L·塞弗伦斯基金，1979年", "p": ["这是传为狩野派画家狩野松荣所作的六曲屏风。它和另一扇成对，描绘中国文人应具备的修养“琴棋书画”——弹琴、下棋、书法和绘画。松树下的原野上，身份高贵的中国士人带着仆从在休憩。", "画面中央两人在下围棋，另一人在旁观看。旁边的桌上放着书和仍装在布套里的琴，等着人来弹。这是一幅娱乐与礼仪兼顾的场景。据美术馆介绍，有个仆人被水里游动的鱼吸引了注意。"], "spots": [["棋盘", "带脚的棋盘，两位士人相对而弈。"], ["士人们", "对弈的两人，和在旁观看的一人。"], ["桌上", "应是放着书和套中之琴的桌子。"], ["仆从", "在桌边侍候的仆从。"], ["看鱼的仆人", "趴在水边，看着鱼游动的仆人。"], ["松树", "在画面上方伸展枝条的大松树。"]]}, "zh-TW": {"title": "琴棋書畫圖屏風（一扇）", "artist": "傳狩野松榮", "date": "16世紀末—17世紀初", "place": "日本（桃山時代）", "game": "圍棋", "medium": "六曲一雙之一，紙本墨畫淡彩", "size": "153×358.6公分", "credit": "約翰·L·塞弗倫斯基金，1979年", "p": ["這是傳為狩野派畫家狩野松榮所作的六曲屏風。它和另一扇成對，描繪中國文人應具備的修養「琴棋書畫」——彈琴、下棋、書法和繪畫。松樹下的原野上，身分高貴的中國士人帶著僕從在休憩。", "畫面中央兩人在下圍棋，另一人在旁觀看。旁邊的桌上放著書和仍裝在布套裡的琴，等著人來彈。這是一幅娛樂與禮儀兼顧的場景。據美術館介紹，有個僕人被水裡游動的魚吸引了注意。"], "spots": [["棋盤", "帶腳的棋盤，兩位士人相對而弈。"], ["士人們", "對弈的兩人，和在旁觀看的一人。"], ["桌上", "應是放著書和套中之琴的桌子。"], ["僕從", "在桌邊侍候的僕從。"], ["看魚的僕人", "趴在水邊，看著魚游動的僕人。"], ["松樹", "在畫面上方伸展枝條的大松樹。"]]}, "ko": {"title": "금기서화도 병풍(한 쌍 중 한 폭)", "artist": "전 가노 쇼에이", "date": "1500년대 말~1600년대 초", "place": "일본(모모야마 시대)", "game": "바둑", "medium": "6폭 한 쌍 중 하나, 종이에 수묵담채", "size": "153×358.6cm", "credit": "존 L. 세버런스 기금, 1979년", "p": ["가노파 화가 가노 쇼에이의 작품으로 전하는 6폭 병풍입니다. 짝을 이루는 다른 한 폭과 함께, 중국 문인이 갖춰야 할 교양 ‘금기서화’ — 거문고를 타고, 바둑을 두고, 글씨를 쓰고, 그림을 그리는 일 — 를 그렸습니다. 소나무 아래 들판에서 지체 높은 중국 신사들이 시종을 거느리고 쉬고 있습니다.", "가운데에서는 두 사람이 바둑을 두고 또 한 사람이 지켜봅니다. 곁의 탁자에는 책과, 아직 천 주머니에 든 금(琴)이 놓여 연주를 기다립니다. 즐거움과 격식이 균형을 이룬 장면입니다. 미술관에 따르면 시종 하나는 물속 물고기의 움직임에 정신이 팔려 있습니다."], "spots": [["바둑판", "다리가 달린 바둑판. 두 신사가 마주 앉아 둡니다."], ["신사들", "바둑을 두는 두 사람과 지켜보는 한 사람."], ["탁자 위", "책과 주머니에 든 금이 놓인 탁자로 보입니다."], ["시종들", "탁자 곁에서 시중드는 시종."], ["물고기에 한눈판 시종", "물가에 엎드려 물고기를 보는 시종."], ["소나무", "화면 위로 가지를 크게 뻗은 소나무."]]}, "es": {"title": "Las cuatro artes (uno de un par de biombos)", "artist": "atribuido a Kanō Shōei", "date": "finales del siglo XVI–principios del XVII", "place": "Japón (periodo Momoyama)", "game": "Go", "medium": "Uno de un par de biombos de seis hojas; tinta y color ligero sobre papel", "size": "153 × 358,6 cm", "credit": "Fondo John L. Severance, 1979", "p": ["Un biombo de seis hojas atribuido a Kanō Shōei, de la escuela Kanō. Con su pareja muestra las «cuatro artes» que se esperaban de un caballero culto chino: tocar el qin, jugar al qi (go), la caligrafía y la pintura. Aquí, caballeros chinos de alto rango y sus criados descansan en el campo bajo los pinos.", "En el centro, dos hombres juegan al go mientras un tercero observa. Cerca, una mesa sostiene libros y un qin aún en su funda de tela, esperando a que lo toquen. La escena equilibra disfrute y formalidad. El museo señala que uno de los criados se distrae con el movimiento de un pez en el agua."], "spots": [["El tablero de go", "Un tablero con patas; dos caballeros juegan frente a frente."], ["Los caballeros", "Dos jugadores y un tercero que mira."], ["La mesa", "Probablemente la mesa con los libros y el qin en su funda."], ["Los criados", "Sirvientes que esperan junto a la mesa."], ["El criado distraído", "Tumbado junto al agua, mira moverse un pez."], ["El pino", "Un gran pino extiende sus ramas sobre la escena."]]}, "fr": {"title": "Les Quatre Arts (l’un d’une paire de paravents)", "artist": "attribué à Kanō Shōei", "date": "fin du XVIe–début du XVIIe siècle", "place": "Japon (époque Momoyama)", "game": "Go", "medium": "L’un d’une paire de paravents à six feuilles ; encre et couleurs légères sur papier", "size": "153 × 358,6 cm", "credit": "Fonds John L. Severance, 1979", "p": ["Un paravent à six feuilles attribué à Kanō Shōei, de l’école Kanō. Avec son pendant, il montre les « Quatre Arts » attendus d’un lettré chinois : jouer du qin, jouer au qi (go), la calligraphie et la peinture. Ici, des gentilshommes chinois et leurs serviteurs se délassent dans la campagne, sous les pins.", "Au centre, deux hommes jouent au go tandis qu’un troisième regarde. Tout près, une table porte des livres et un qin encore dans son étui de tissu, qui attend qu’on en joue. La scène équilibre plaisir et bienséance. Le musée relève qu’un des serviteurs est distrait par le mouvement d’un poisson dans l’eau."], "spots": [["Le goban", "Un plateau sur pieds ; deux gentilshommes jouent face à face."], ["Les gentilshommes", "Deux joueurs et un troisième qui regarde."], ["La table", "Sans doute la table aux livres et au qin dans son étui."], ["Les serviteurs", "Des serviteurs qui attendent près de la table."], ["Le serviteur distrait", "Allongé au bord de l’eau, il regarde un poisson."], ["Le pin", "Un grand pin étend ses branches au-dessus de la scène."]]}, "pt": {"title": "As quatro artes (um de um par de biombos)", "artist": "atribuído a Kanō Shōei", "date": "fim do século XVI–início do XVII", "place": "Japão (período Momoyama)", "game": "Go", "medium": "Um de um par de biombos de seis folhas; tinta e cor leve sobre papel", "size": "153 × 358,6 cm", "credit": "Fundo John L. Severance, 1979", "p": ["Um biombo de seis folhas atribuído a Kanō Shōei, da escola Kanō. Com seu par, mostra as «quatro artes» esperadas de um cavalheiro culto chinês: tocar o qin, jogar qi (go), caligrafia e pintura. Aqui, cavalheiros chineses de alta posição e seus criados descansam no campo, sob os pinheiros.", "No centro, dois homens jogam go enquanto um terceiro observa. Perto, uma mesa guarda livros e um qin ainda no estojo de pano, à espera de ser tocado. A cena equilibra prazer e formalidade. O museu observa que um dos criados se distrai com o movimento de um peixe na água."], "spots": [["O tabuleiro de go", "Um tabuleiro com pés; dois cavalheiros jogam frente a frente."], ["Os cavalheiros", "Dois jogadores e um terceiro que observa."], ["A mesa", "Provavelmente a mesa com os livros e o qin no estojo."], ["Os criados", "Criados que aguardam junto à mesa."], ["O criado distraído", "Deitado à beira da água, olha um peixe se mover."], ["O pinheiro", "Um grande pinheiro estende os galhos sobre a cena."]]}, "de": {"title": "Die vier Künste (einer von zwei Stellschirmen)", "artist": "Kanō Shōei zugeschrieben", "date": "spätes 16.–frühes 17. Jahrhundert", "place": "Japan (Momoyama-Zeit)", "game": "Go", "medium": "Einer von zwei sechsteiligen Stellschirmen; Tusche und leichte Farben auf Papier", "size": "153 × 358,6 cm", "credit": "John L. Severance Fund, 1979", "p": ["Ein sechsteiliger Stellschirm, Kanō Shōei aus der Kanō-Schule zugeschrieben. Zusammen mit seinem Gegenstück zeigt er die „vier Künste“, die man von einem gebildeten chinesischen Herrn erwartete: Qin spielen, Qi (Go) spielen, Kalligrafie und Malerei. Hier ruhen vornehme chinesische Herren mit ihren Dienern unter Kiefern auf dem Land.", "In der Mitte spielen zwei Männer Go, ein dritter schaut zu. Daneben stehen auf einem Tisch Bücher und eine Qin, noch in ihrer Stoffhülle, die darauf wartet, gespielt zu werden. Die Szene hält Vergnügen und Förmlichkeit im Gleichgewicht. Das Museum weist darauf hin, dass einer der Diener von einem Fisch im Wasser abgelenkt ist."], "spots": [["Das Go-Brett", "Ein Brett mit Füßen; zwei Herren spielen einander gegenüber."], ["Die Herren", "Zwei Spieler und ein dritter, der zuschaut."], ["Der Tisch", "Wohl der Tisch mit den Büchern und der Qin in ihrer Hülle."], ["Die Diener", "Diener, die beim Tisch warten."], ["Der abgelenkte Diener", "Am Wasser liegend, schaut er einem Fisch zu."], ["Die Kiefer", "Eine große Kiefer breitet ihre Zweige über die Szene."]]}, "ru": {"title": "Четыре искусства (одна из пары ширм)", "artist": "приписывается Кано Сёэю", "date": "конец XVI — начало XVII века", "place": "Япония (период Момояма)", "game": "Го", "medium": "Одна из пары шестистворчатых ширм; тушь и лёгкие краски на бумаге", "size": "153 × 358,6 см", "credit": "Фонд Джона Л. Северанса, 1979", "p": ["Шестистворчатая ширма, приписываемая Кано Сёэю из школы Кано. Вместе с парной ширмой она изображает «четыре искусства», которыми должен был владеть образованный китайский господин: игру на цине, игру в ци (го), каллиграфию и живопись. Здесь знатные китайцы со слугами отдыхают на природе под соснами.", "В центре двое играют в го, а третий наблюдает. Рядом на столе — книги и цинь, ещё в матерчатом чехле, ожидающий игры. Сцена соединяет удовольствие и благопристойность. Музей отмечает, что один из слуг отвлёкся, глядя на рыбу в воде."], "spots": [["Доска для го", "Доска на ножках; двое господ играют друг против друга."], ["Господа", "Двое игроков и третий, который смотрит."], ["Стол", "Вероятно, стол с книгами и цинем в чехле."], ["Слуги", "Слуги ждут у стола."], ["Отвлёкшийся слуга", "Лёжа у воды, он смотрит на рыбу."], ["Сосна", "Большая сосна раскинула ветви над сценой."]]}, "tr": {"title": "Dört Hüner (bir çift paravandan biri)", "artist": "Kanō Shōei’ye atfedilir", "date": "16. yüzyıl sonu–17. yüzyıl başı", "place": "Japonya (Momoyama dönemi)", "game": "Go", "medium": "Bir çift altı kanatlı paravandan biri; kâğıt üzerine mürekkep ve hafif renk", "size": "153 × 358,6 cm", "credit": "John L. Severance Fonu, 1979", "p": ["Kanō okulundan Kanō Shōei’ye atfedilen altı kanatlı bir paravan. Eşiyle birlikte kültürlü bir Çinli beyefendiden beklenen “dört hüner”i gösterir: qin çalmak, qi (go) oynamak, hat ve resim. Burada yüksek mevkili Çinli beyefendiler hizmetkârlarıyla çamların altında kırda dinleniyor.", "Ortada iki adam go oynuyor, üçüncüsü izliyor. Yanlarındaki masada kitaplar ve hâlâ kumaş kılıfında duran, çalınmayı bekleyen bir qin var. Sahne eğlenceyle resmiyeti dengeliyor. Müze, hizmetkârlardan birinin sudaki bir balığın hareketine dalıp gittiğine dikkat çekiyor."], "spots": [["Go tahtası", "Ayaklı bir tahta; iki beyefendi karşılıklı oynuyor."], ["Beyefendiler", "İki oyuncu ve izleyen üçüncüsü."], ["Masa", "Büyük olasılıkla kitapların ve kılıfındaki qin’in durduğu masa."], ["Hizmetkârlar", "Masanın yanında bekleyen hizmetkârlar."], ["Dalgın hizmetkâr", "Su kıyısına uzanmış, bir balığı izliyor."], ["Çam", "Sahnenin üstüne dallarını yayan büyük bir çam."]]}, "id": {"title": "Empat Keterampilan (satu dari sepasang layar lipat)", "artist": "dikaitkan dengan Kanō Shōei", "date": "akhir abad ke-16–awal abad ke-17", "place": "Jepang (zaman Momoyama)", "game": "Go", "medium": "Satu dari sepasang layar lipat enam panel; tinta dan sedikit warna di atas kertas", "size": "153 × 358,6 cm", "credit": "Dana John L. Severance, 1979", "p": ["Layar lipat enam panel yang dikaitkan dengan Kanō Shōei dari aliran Kanō. Bersama pasangannya, layar ini menggambarkan “empat keterampilan” yang diharapkan dari seorang pria terpelajar Tiongkok: memainkan qin, bermain qi (go), kaligrafi, dan melukis. Di sini para pria Tiongkok terpandang beserta pelayan mereka bersantai di padang di bawah pohon pinus.", "Di tengah, dua orang bermain go sementara orang ketiga menonton. Di dekatnya, sebuah meja memuat buku dan qin yang masih di dalam sarung kainnya, menunggu dimainkan. Adegan ini menyeimbangkan kesenangan dan tata krama. Museum mencatat bahwa salah satu pelayan teralihkan perhatiannya oleh gerak ikan di air."], "spots": [["Papan go", "Papan berkaki; dua pria bermain berhadapan."], ["Para pria", "Dua pemain dan orang ketiga yang menonton."], ["Meja", "Kemungkinan meja berisi buku dan qin dalam sarungnya."], ["Para pelayan", "Pelayan yang menunggu di dekat meja."], ["Pelayan yang teralihkan", "Berbaring di tepi air, memperhatikan ikan."], ["Pinus", "Pinus besar membentangkan dahannya di atas adegan."]]}, "hi": {"title": "चार कलाएँ (परदों की जोड़ी में से एक)", "artist": "कानो शोएई को श्रेय", "date": "16वीं सदी का अंत–17वीं सदी की शुरुआत", "place": "जापान (मोमोयामा काल)", "game": "गो", "medium": "छह पटों वाले परदों की जोड़ी में से एक; काग़ज़ पर स्याही और हल्के रंग", "size": "153 × 358.6 सेमी", "credit": "जॉन एल. सेवरेंस निधि, 1979", "p": ["कानो शैली के चित्रकार कानो शोएई को श्रेय दिया जाने वाला छह पटों का परदा। अपनी जोड़ी के साथ यह उन “चार कलाओं” को दिखाता है जो एक सुसंस्कृत चीनी सज्जन से अपेक्षित थीं: छिन बजाना, छी (गो) खेलना, सुलेख और चित्रकला। यहाँ ऊँचे दर्जे के चीनी सज्जन अपने सेवकों के साथ चीड़ों के नीचे खुले मैदान में आराम कर रहे हैं।", "बीच में दो व्यक्ति गो खेल रहे हैं और तीसरा देख रहा है। पास की मेज़ पर किताबें और कपड़े के खोल में रखा छिन है, जो बजाए जाने की प्रतीक्षा में है। दृश्य में आनंद और शिष्टता का संतुलन है। संग्रहालय बताता है कि एक सेवक पानी में मछली की हलचल देखने में खोया है।"], "spots": [["गो की बिसात", "पायों वाली बिसात; दो सज्जन आमने‑सामने खेल रहे हैं।"], ["सज्जन", "दो खिलाड़ी और देखता हुआ तीसरा।"], ["मेज़", "संभवतः किताबों और खोल में रखे छिन वाली मेज़।"], ["सेवक", "मेज़ के पास खड़े सेवक।"], ["मछली में खोया सेवक", "पानी के किनारे लेटकर मछली देखता सेवक।"], ["चीड़", "दृश्य के ऊपर डालियाँ फैलाता बड़ा चीड़।"]]}, "ar": {"title": "الفنون الأربعة (أحد زوج من الستائر)", "artist": "يُنسب إلى كانو شوئي", "date": "أواخر القرن السادس عشر–أوائل السابع عشر", "place": "اليابان (عصر موموياما)", "game": "الغو", "medium": "أحد زوج من الستائر ذات الألواح الستة؛ حبر وألوان خفيفة على ورق", "size": "153 × 358.6 سم", "credit": "صندوق جون ل. سيفيرانس، 1979", "p": ["ستارة قابلة للطي من ستة ألواح تُنسب إلى كانو شوئي من مدرسة كانو. وهي مع قرينتها تصوّر «الفنون الأربعة» المنتظرة من الرجل الصيني المثقف: العزف على آلة التشين، ولعب التشي (الغو)، والخط، والرسم. وهنا يستريح سادة صينيون من علية القوم مع خدمهم في الريف تحت أشجار الصنوبر.", "في الوسط يلعب رجلان الغو ويتفرج ثالث. وعلى طاولة قريبة كتب وآلة تشين ما زالت في غلافها القماشي تنتظر من يعزف عليها. والمشهد يوازن بين المتعة والوقار. ويلفت المتحف إلى أن أحد الخدم شغلته حركة سمكة في الماء."], "spots": [["لوح الغو", "لوح بقوائم يلعب عليه سيدان متقابلان."], ["السادة", "لاعبان وثالث يتفرج."], ["الطاولة", "على الأرجح الطاولة التي عليها الكتب والتشين في غلافه."], ["الخدم", "خدم ينتظرون قرب الطاولة."], ["الخادم الشارد", "مستلقٍ عند الماء يراقب سمكة."], ["الصنوبرة", "صنوبرة كبيرة تمد أغصانها فوق المشهد."]]}}};
  Object.keys(A).forEach(id => Object.keys(A[id]).forEach(l => { if (T[l]) T[l][id] = A[id][l]; })); })(window.MUSEUM_PAINT_T);
/* (2026-11-24) four more from The Cleveland Museum of Art (CC0): the Horse Stable screen 1934.373.1, the Goryeo celadon pitcher 1917.356, the Kangra chaupar drawing 1936.683, Vuillard’s Game of Checkers 1951.65.2 */
(T => { const A = {"umaya": {"ja": {"title": "厩図屏風（碁と将棋の縁側）", "artist": "作者不明", "date": "1500年代前半", "place": "日本（室町時代）", "game": "囲碁・将棋", "medium": "六曲一双のうち一隻。紙本着色・金", "size": "146.1×346.6cm", "credit": "エドワード・L・ウィッテモア基金による購入、1934年", "p": ["6枚のパネルをつないだ屏風で、左右2つで一組になるうちの片方です。厩につながれた自慢の馬たちがおもな主題ですが、手前の縁側でも、にぎやかなことが起きています。", "縁側では人びとが2つのゲームで勝負しています。左は碁、右は将棋。美術館の解説によれば、暴れる馬たちと、じっと考える盤上の勝負とのかけあいが、場をいきいきとさせています。日本では猿が馬の守り神とされ、厩で猿を飼うこともありました。"], "spots": [["碁盤", "細かい升目に黒い石が並ぶ碁盤。"], ["烏帽子の2人", "黒い烏帽子の男たち。緑の衣の男が盤に手をのばし、赤い衣の男がそばで見ています。"], ["将棋盤", "升目の大きな盤。碁盤とくらべると、升目がずっと少ないのがわかります。"], ["笑う相手", "坊主頭の僧が駒をつまみ、向かいの男は頭に手をやって大笑い。どちらかが一本取ったのでしょうか。"], ["猿", "縁側の端に、赤い服を着た猿でしょうか。"], ["馬", "前脚を上げてはねる黒い馬。綱でつながれています。"]]}, "en": {"title": "Horse Stable (go and shogi on the veranda)", "artist": "Unknown", "date": "Early 1500s", "place": "Japan (Muromachi period)", "game": "Go and shogi", "medium": "One of a pair of six-panel folding screens; ink, color and gold on paper", "size": "146.1 × 346.6 cm", "credit": "Edward L. Whittemore Fund, 1934", "p": ["This folding screen of six joined panels is one of a pair. Prized horses in their stalls may be the main theme, but a lot is happening on the veranda in front.", "There, people challenge one another at two different board games: go on the left and shogi on the right. As the museum puts it, the lively mood comes from the interplay of the restless horses and the quiet strategy of the games. In Japan monkeys were thought to protect horses, and were sometimes kept in stables."], "spots": [["The go board", "A finely ruled board with black stones on it."], ["Two men in black caps", "Men in tall black eboshi caps: the one in green reaches for the board, the one in red looks on."], ["The shogi board", "A board with large squares — far fewer than on the go board."], ["The laughing opponent", "A shaven-headed monk picks up a piece while the man opposite clutches his head and roars with laughter. Has someone just scored a point?"], ["A monkey", "At the end of the veranda — a monkey in a red coat?"], ["A horse", "A black horse rears up, held by its ropes."]]}, "zh": {"title": "马厩图屏风（廊下的围棋与将棋）", "artist": "作者不详", "date": "16世纪前期", "place": "日本（室町时代）", "game": "围棋、将棋", "medium": "六曲一双屏风之一；纸本设色、金", "size": "146.1×346.6厘米", "credit": "爱德华·L·惠特莫尔基金购藏，1934年", "p": ["这是由6扇连成的屏风，左右两件为一组，这是其中之一。主题或许是马厩里拴着的名马，但前面的廊下也热闹非凡。", "廊下的人们在下两种棋：左边是围棋，右边是将棋。按美术馆的解说，躁动的马匹与静心谋划的棋局相映成趣，使画面充满生气。在日本，猴子被视为马的守护者，马厩里有时也养猴。"], "spots": [["围棋盘", "画着细密格线、摆着黑子的棋盘。"], ["戴乌帽子的两人", "头戴黑色乌帽子的男人们：穿绿衣的伸手向棋盘，穿红衣的在旁观看。"], ["将棋盘", "格子很大的棋盘，与围棋盘相比，格数少得多。"], ["大笑的对手", "光头的僧人拈起棋子，对面的男人抱着头大笑。是谁刚占了上风吗？"], ["猴子", "廊下的一端，好像是一只穿红衣的猴子。"], ["马", "扬起前蹄的黑马，被绳子拴着。"]]}, "zh-TW": {"title": "馬廄圖屏風（廊下的圍棋與將棋）", "artist": "作者不詳", "date": "16世紀前期", "place": "日本（室町時代）", "game": "圍棋、將棋", "medium": "六曲一雙屏風之一；紙本設色、金", "size": "146.1×346.6公分", "credit": "愛德華·L·惠特莫爾基金購藏，1934年", "p": ["這是由6扇連成的屏風，左右兩件為一組，這是其中之一。主題或許是馬廄裡拴著的名馬，但前面的廊下也熱鬧非凡。", "廊下的人們在下兩種棋：左邊是圍棋，右邊是將棋。依美術館的解說，躁動的馬匹與靜心謀劃的棋局相映成趣，使畫面充滿生氣。在日本，猴子被視為馬的守護者，馬廄裡有時也養猴。"], "spots": [["圍棋盤", "畫著細密格線、擺著黑子的棋盤。"], ["戴烏帽子的兩人", "頭戴黑色烏帽子的男人們：穿綠衣的伸手向棋盤，穿紅衣的在旁觀看。"], ["將棋盤", "格子很大的棋盤，與圍棋盤相比，格數少得多。"], ["大笑的對手", "光頭的僧人拈起棋子，對面的男人抱著頭大笑。是誰剛占了上風嗎？"], ["猴子", "廊下的一端，好像是一隻穿紅衣的猴子。"], ["馬", "揚起前蹄的黑馬，被繩子拴著。"]]}, "ko": {"title": "마구간 그림 병풍(툇마루의 바둑과 쇼기)", "artist": "작자 미상", "date": "1500년대 전반", "place": "일본(무로마치 시대)", "game": "바둑·쇼기", "medium": "6폭 한 쌍 중 한 점. 종이에 채색·금", "size": "146.1×346.6cm", "credit": "에드워드 L. 휘트모어 기금 구입, 1934년", "p": ["6폭을 이은 병풍으로, 좌우 두 점이 한 쌍을 이루는 가운데 하나입니다. 마구간에 매인 귀한 말들이 주제이지만, 앞쪽 툇마루에서도 떠들썩한 일이 벌어지고 있습니다.", "툇마루에서는 사람들이 두 가지 게임으로 승부를 겨룹니다. 왼쪽은 바둑, 오른쪽은 쇼기입니다. 미술관의 해설에 따르면 날뛰는 말과 차분히 수를 읽는 판 위의 승부가 어우러져 장면에 활기를 줍니다. 일본에서는 원숭이가 말을 지켜 준다고 여겨 마구간에서 원숭이를 기르기도 했습니다."], "spots": [["바둑판", "촘촘한 줄 위에 검은 돌이 놓인 바둑판."], ["에보시를 쓴 두 사람", "검은 에보시를 쓴 남자들. 초록 옷의 남자가 판으로 손을 뻗고, 붉은 옷의 남자가 곁에서 봅니다."], ["쇼기판", "칸이 큰 판. 바둑판과 비교하면 칸 수가 훨씬 적습니다."], ["웃는 상대", "삭발한 승려가 말을 집고, 맞은편 남자는 머리에 손을 얹고 크게 웃습니다. 누가 한 수 이긴 걸까요?"], ["원숭이", "툇마루 끝에 붉은 옷을 입은 원숭이일까요?"], ["말", "앞다리를 들고 날뛰는 검은 말. 줄에 매여 있습니다."]]}, "es": {"title": "Biombo de las caballerizas (go y shogi en la galería)", "artist": "Anónimo", "date": "Principios del siglo XVI", "place": "Japón (periodo Muromachi)", "game": "Go y shogi", "medium": "Uno de una pareja de biombos de seis hojas; tinta, color y oro sobre papel", "size": "146,1 × 346,6 cm", "credit": "Edward L. Whittemore Fund, 1934", "p": ["Este biombo de seis hojas unidas es uno de una pareja. Los preciados caballos de las cuadras quizá sean el tema principal, pero en la galería de delante ocurren muchas cosas.", "Allí la gente se desafía en dos juegos distintos: go a la izquierda y shogi a la derecha. Según el museo, el ambiente animado nace del contraste entre los caballos inquietos y la estrategia serena de los juegos. En Japón se creía que los monos protegían a los caballos, y a veces se tenían en las cuadras."], "spots": [["El tablero de go", "Un tablero de líneas finas con piedras negras."], ["Dos hombres con gorro negro", "Hombres con alto eboshi negro: el de verde tiende la mano al tablero, el de rojo mira."], ["El tablero de shogi", "Un tablero de casillas grandes, muchas menos que en el de go."], ["El rival que ríe", "Un monje rapado coge una pieza mientras el hombre de enfrente se lleva la mano a la cabeza y ríe a carcajadas. ¿Alguien acaba de anotarse un tanto?"], ["Un mono", "Al final de la galería, ¿un mono con chaqueta roja?"], ["Un caballo", "Un caballo negro se encabrita, sujeto por sus cuerdas."]]}, "fr": {"title": "Paravent des écuries (go et shogi sur la véranda)", "artist": "Anonyme", "date": "Début du XVIe siècle", "place": "Japon (époque Muromachi)", "game": "Go et shogi", "medium": "L’un d’une paire de paravents à six feuilles ; encre, couleurs et or sur papier", "size": "146,1 × 346,6 cm", "credit": "Edward L. Whittemore Fund, 1934", "p": ["Ce paravent de six feuilles assemblées forme une paire avec un autre. Les chevaux de prix dans leurs stalles en sont peut-être le sujet principal, mais il se passe beaucoup de choses sur la véranda, au premier plan.", "On s’y affronte à deux jeux différents : le go à gauche, le shogi à droite. Selon le musée, la vivacité de la scène naît du jeu entre les chevaux agités et la stratégie tranquille des parties. Au Japon, on pensait que les singes protégeaient les chevaux, et l’on en gardait parfois dans les écuries."], "spots": [["Le goban", "Un plateau finement quadrillé, avec des pierres noires."], ["Deux hommes en bonnet noir", "Des hommes coiffés du haut eboshi noir : celui en vert tend la main vers le plateau, celui en rouge regarde."], ["Le plateau de shogi", "De grandes cases, bien moins nombreuses que sur le goban."], ["L’adversaire hilare", "Un moine au crâne rasé saisit une pièce tandis que l’homme en face se tient la tête en riant aux éclats. Quelqu’un vient-il de marquer un point ?"], ["Un singe", "Au bout de la véranda, un singe en veste rouge ?"], ["Un cheval", "Un cheval noir se cabre, retenu par ses cordes."]]}, "pt": {"title": "Biombo das cavalariças (go e shogi na varanda)", "artist": "Autor desconhecido", "date": "Início do século XVI", "place": "Japão (período Muromachi)", "game": "Go e shogi", "medium": "Um de um par de biombos de seis folhas; tinta, cor e ouro sobre papel", "size": "146,1 × 346,6 cm", "credit": "Edward L. Whittemore Fund, 1934", "p": ["Este biombo de seis folhas unidas é um de um par. Os cavalos valiosos nas baias talvez sejam o tema principal, mas muita coisa acontece na varanda à frente.", "Ali as pessoas desafiam-se em dois jogos diferentes: go à esquerda e shogi à direita. Segundo o museu, a animação vem do contraste entre os cavalos inquietos e a estratégia serena dos jogos. No Japão acreditava-se que os macacos protegiam os cavalos, e por vezes eram mantidos nas cavalariças."], "spots": [["O tabuleiro de go", "Um tabuleiro de linhas finas com pedras pretas."], ["Dois homens de barrete preto", "Homens com alto eboshi preto: o de verde estende a mão ao tabuleiro, o de vermelho observa."], ["O tabuleiro de shogi", "Casas grandes, muito menos do que no tabuleiro de go."], ["O adversário que ri", "Um monge de cabeça rapada pega numa peça enquanto o homem em frente leva a mão à cabeça e ri às gargalhadas. Alguém acabou de marcar um ponto?"], ["Um macaco", "No fim da varanda, um macaco de casaco vermelho?"], ["Um cavalo", "Um cavalo preto empina-se, preso pelas cordas."]]}, "de": {"title": "Stallschirm (Go und Shogi auf der Veranda)", "artist": "Unbekannt", "date": "Frühes 16. Jahrhundert", "place": "Japan (Muromachi-Zeit)", "game": "Go und Shogi", "medium": "Einer von zwei sechsteiligen Stellschirmen; Tusche, Farben und Gold auf Papier", "size": "146,1 × 346,6 cm", "credit": "Edward L. Whittemore Fund, 1934", "p": ["Dieser Stellschirm aus sechs verbundenen Feldern ist einer von einem Paar. Die wertvollen Pferde in ihren Ständen mögen das Hauptthema sein, doch auf der Veranda davor ist viel los.", "Dort fordern sich Menschen in zwei Brettspielen heraus: links Go, rechts Shogi. Wie das Museum schreibt, lebt die Szene vom Wechselspiel zwischen den unruhigen Pferden und der stillen Strategie der Spiele. In Japan galten Affen als Beschützer der Pferde und wurden manchmal in Ställen gehalten."], "spots": [["Das Go-Brett", "Ein fein liniertes Brett mit schwarzen Steinen."], ["Zwei Männer mit schwarzer Kappe", "Männer mit hoher schwarzer Eboshi-Kappe: der in Grün greift zum Brett, der in Rot schaut zu."], ["Das Shogi-Brett", "Große Felder – viel weniger als auf dem Go-Brett."], ["Der lachende Gegner", "Ein kahlgeschorener Mönch nimmt einen Stein, während der Mann gegenüber sich an den Kopf fasst und laut lacht. Hat gerade jemand gepunktet?"], ["Ein Affe", "Am Ende der Veranda – ein Affe in rotem Rock?"], ["Ein Pferd", "Ein schwarzes Pferd bäumt sich auf, von Seilen gehalten."]]}, "ru": {"title": "Ширма с конюшней (го и сёги на веранде)", "artist": "Неизвестный мастер", "date": "Начало XVI века", "place": "Япония (период Муромати)", "game": "Го и сёги", "medium": "Одна из пары шестистворчатых ширм; тушь, краски и золото на бумаге", "size": "146,1 × 346,6 см", "credit": "Фонд Эдварда Л. Уиттмора, 1934", "p": ["Эта ширма из шести соединённых створок — одна из пары. Главная тема, возможно, ценные кони в стойлах, но и на веранде перед ними много всего происходит.", "Там люди состязаются в двух разных играх: слева го, справа сёги. Как пишет музей, живость сцене придаёт перекличка беспокойных коней и тихой стратегии игр. В Японии считалось, что обезьяны охраняют лошадей, и их иногда держали в конюшнях."], "spots": [["Доска го", "Доска с частой разлиновкой и чёрными камнями."], ["Двое в чёрных шапках", "Мужчины в высоких чёрных шапках эбоси: тот, что в зелёном, тянется к доске, тот, что в красном, смотрит."], ["Доска сёги", "Крупные клетки — гораздо меньше, чем на доске го."], ["Смеющийся соперник", "Бритоголовый монах берёт фигуру, а мужчина напротив схватился за голову и хохочет. Кто-то только что выиграл очко?"], ["Обезьяна", "В конце веранды — обезьяна в красной куртке?"], ["Конь", "Чёрный конь встаёт на дыбы, удерживаемый верёвками."]]}, "tr": {"title": "Ahır Paravanı (verandada go ve shogi)", "artist": "Bilinmiyor", "date": "16. yüzyılın başı", "place": "Japonya (Muromachi dönemi)", "game": "Go ve shogi", "medium": "Altı kanatlı bir çift paravandan biri; kâğıt üzerine mürekkep, renk ve altın", "size": "146,1 × 346,6 cm", "credit": "Edward L. Whittemore Fund, 1934", "p": ["Altı kanadın birleştirildiği bu paravan bir çiftin tekidir. Asıl konu bölmelerdeki değerli atlar olabilir, ama öndeki verandada da pek çok şey oluyor.", "Orada insanlar iki ayrı oyunda yarışıyor: solda go, sağda shogi. Müzeye göre sahnenin canlılığı, huzursuz atlarla oyunların sessiz stratejisi arasındaki karşıtlıktan doğuyor. Japonyada maymunların atları koruduğuna inanılır, ahırlarda bazen maymun beslenirdi."], "spots": [["Go tahtası", "İnce çizgili, üzerinde siyah taşlar olan bir tahta."], ["Siyah başlıklı iki adam", "Uzun siyah eboshi başlıklı adamlar: yeşilli olan tahtaya uzanıyor, kırmızılı olan izliyor."], ["Shogi tahtası", "Büyük kareli bir tahta; go tahtasındakinden çok daha az kare var."], ["Gülen rakip", "Başı tıraşlı bir keşiş bir taş alırken karşısındaki adam elini başına koyup kahkaha atıyor. Biri az önce puan mı aldı?"], ["Bir maymun", "Verandanın ucunda, kırmızı giysili bir maymun mu?"], ["Bir at", "İplerle bağlı siyah bir at şaha kalkıyor."]]}, "id": {"title": "Sekat Lipat Istal Kuda (go dan shogi di beranda)", "artist": "Tidak diketahui", "date": "Awal abad ke-16", "place": "Jepang (zaman Muromachi)", "game": "Go dan shogi", "medium": "Satu dari sepasang sekat lipat enam panel; tinta, warna, dan emas di atas kertas", "size": "146,1 × 346,6 cm", "credit": "Edward L. Whittemore Fund, 1934", "p": ["Sekat lipat dari enam panel yang disambung ini adalah satu dari sepasang. Kuda-kuda berharga di kandangnya mungkin tema utamanya, tetapi banyak hal terjadi di beranda depan.", "Di sana orang-orang saling menantang dalam dua permainan berbeda: go di kiri dan shogi di kanan. Menurut museum, suasana yang hidup muncul dari perpaduan kuda yang gelisah dan strategi tenang permainan. Di Jepang monyet dianggap melindungi kuda, dan kadang dipelihara di istal."], "spots": [["Papan go", "Papan bergaris halus dengan batu hitam."], ["Dua pria bertopi hitam", "Pria bertopi eboshi hitam tinggi: yang berbaju hijau menjangkau papan, yang berbaju merah menonton."], ["Papan shogi", "Petaknya besar — jauh lebih sedikit daripada papan go."], ["Lawan yang tertawa", "Seorang biksu berkepala gundul mengambil bidak, sementara pria di depannya memegang kepala sambil tertawa keras. Apakah seseorang baru mencetak angka?"], ["Seekor monyet", "Di ujung beranda — monyet berbaju merah?"], ["Seekor kuda", "Kuda hitam mengangkat kaki depannya, ditahan tali."]]}, "hi": {"title": "अस्तबल का परदा (बरामदे पर गो और शोगी)", "artist": "अज्ञात", "date": "1500 के दशक का आरंभ", "place": "जापान (मुरोमाची काल)", "game": "गो और शोगी", "medium": "छह पटों वाले परदों की जोड़ी में से एक; काग़ज़ पर स्याही, रंग और सोना", "size": "146.1 × 346.6 सेमी", "credit": "एडवर्ड एल. व्हिटमोर फ़ंड, 1934", "p": ["छह जुड़े पटों वाला यह मोड़ने वाला परदा एक जोड़ी में से एक है। मुख्य विषय शायद अस्तबल में बँधे क़ीमती घोड़े हैं, पर सामने के बरामदे पर भी बहुत कुछ हो रहा है।", "वहाँ लोग दो अलग खेलों में मुक़ाबला कर रहे हैं: बाईं ओर गो, दाईं ओर शोगी। संग्रहालय के अनुसार बेचैन घोड़ों और खेलों की शांत रणनीति का मेल दृश्य को जीवंत बनाता है। जापान में माना जाता था कि बंदर घोड़ों की रक्षा करते हैं, और कभी-कभी उन्हें अस्तबल में रखा जाता था।"], "spots": [["गो की बिसात", "बारीक रेखाओं वाली बिसात, जिस पर काले पत्थर हैं।"], ["काली टोपी वाले दो आदमी", "ऊँची काली एबोशी टोपी वाले आदमी: हरे वाला बिसात की ओर हाथ बढ़ाता है, लाल वाला देखता है।"], ["शोगी की बिसात", "बड़े खानों वाली बिसात — गो की बिसात से कहीं कम खाने।"], ["हँसता प्रतिद्वंद्वी", "मुंडे सिर वाला भिक्षु एक मोहरा उठाता है, और सामने वाला आदमी सिर पकड़कर ठहाका लगाता है। क्या किसी ने अभी बाज़ी मारी?"], ["एक बंदर", "बरामदे के सिरे पर — लाल कोट पहने बंदर?"], ["एक घोड़ा", "रस्सियों से बँधा काला घोड़ा अगले पैर उठाकर उछलता है।"]]}, "ar": {"title": "ستارة الإسطبل (الغو والشوغي على الشرفة)", "artist": "مجهول", "date": "أوائل القرن السادس عشر", "place": "اليابان (عصر موروماتشي)", "game": "الغو والشوغي", "medium": "واحدة من زوج من الستائر القابلة للطي ذات الألواح الستة؛ حبر وألوان وذهب على ورق", "size": "146.1 × 346.6 سم", "credit": "صندوق إدوارد ل. ويتمور، 1934", "p": ["هذه الستارة المؤلفة من ستة ألواح متصلة واحدة من زوج. قد تكون الخيول الثمينة في حظائرها هي الموضوع الأساسي، لكن الكثير يجري على الشرفة في المقدمة.", "هناك يتبارى الناس في لعبتين مختلفتين: الغو على اليسار والشوغي على اليمين. ويرى المتحف أن حيوية المشهد تنبع من التقابل بين الخيول القلقة والاستراتيجية الهادئة للعبتين. وفي اليابان كان يُعتقد أن القردة تحمي الخيول، فكانت تُربّى أحيانًا في الإسطبلات."], "spots": [["رقعة الغو", "رقعة دقيقة الخطوط عليها أحجار سوداء."], ["رجلان بقلنسوتين سوداوين", "رجال يعتمرون قلنسوة الإيبوشي السوداء العالية: صاحب الثوب الأخضر يمد يده إلى الرقعة، وصاحب الأحمر يتفرّج."], ["رقعة الشوغي", "رقعة خاناتها كبيرة — أقل بكثير من رقعة الغو."], ["الخصم الضاحك", "راهب حليق الرأس يلتقط قطعة، والرجل المقابل يمسك رأسه ويقهقه. هل سجّل أحدهما نقطة للتو؟"], ["قرد", "في طرف الشرفة — قرد يرتدي سترة حمراء؟"], ["حصان", "حصان أسود يرفع قائمتيه الأماميتين، مشدود بالحبال."]]}}, "goryeo": {"ja": {"title": "碁を打つ人の象嵌青磁の水注", "artist": "作者不明", "date": "1200年代", "place": "朝鮮半島（高麗）", "game": "囲碁（パドゥク）", "medium": "青磁、白土と黒土の象嵌", "size": "高さ20.4cm、径14.3cm", "credit": "ジョン・L・セヴェランス寄贈、1917年", "p": ["高麗の青磁の水注（注ぎ口と取っ手のある器）です。器に彫った線に白と黒の土をうめ、釉をかけて焼く「象嵌」は高麗の陶工が得意とした技で、丸い枠の中に、柳の下に座る2人が白く浮かび上がっています。", "2人のあいだには盤があり、美術館はこの場面を、碁（韓国語でパドゥク）を打つ姿に通じるものとみています。琴・碁・書・画の「四芸」は文人が身につけるべきたしなみとされ、その優雅な集いは工芸の図柄にもなりました。人物を表した高麗の象嵌青磁はめずらしいものです。"], "spots": [["盤", "2人のあいだの盤。白い土で四角く表されています。"], ["左の人", "盤に向かって座る人。"], ["右の人", "向かいに座る相手。"], ["柳", "2人の頭上にたれる柳の枝。黒い土で描かれています。"], ["雲の枠", "丸い枠のまわりを、渦を巻く雲のような文様がめぐります。"], ["貫入", "釉の表面の細かなひび（貫入）。焼いたあと冷えるとき、土と釉の縮み方の違いでできます。"]]}, "en": {"title": "Pitcher with inlaid figures playing go", "artist": "Unknown", "date": "1200s", "place": "Korea (Goryeo dynasty)", "game": "Go (baduk)", "medium": "Celadon ware with inlaid white and black slip", "size": "H. 20.4 cm, diam. 14.3 cm", "credit": "Gift of John L. Severance, 1917", "p": ["A Goryeo celadon pitcher, with a spout and a handle. Inlay — carving lines into the clay, filling them with white and black slip, then glazing and firing — was the specialty of Goryeo potters, and here two figures sitting under a willow stand out in white inside a round frame.", "Between them is a board, and the museum compares the scene to pictures of playing go — baduk in Korean. Playing the zither, go, calligraphy and painting were the “four accomplishments” of the cultivated scholar, and their elegant gatherings became designs for craftsmen too. Korean inlaid celadon showing people is rare."], "spots": [["The board", "The board between the two, shown as a white square."], ["The figure on the left", "Seated, facing the board."], ["The figure on the right", "The opponent, sitting across from him."], ["The willow", "Willow branches hang over them, drawn in black slip."], ["The cloud frame", "Swirling cloud-like scrolls run around the round frame."], ["The crackle", "Fine cracks in the glaze. They form as the pot cools, because clay and glaze shrink by different amounts."]]}, "zh": {"title": "下棋人物纹镶嵌青瓷注子", "artist": "作者不详", "date": "13世纪", "place": "朝鲜半岛（高丽）", "game": "围棋（韩语“巴督”）", "medium": "青瓷，白土与黑土镶嵌", "size": "高20.4厘米，径14.3厘米", "credit": "约翰·L·塞弗伦斯捐赠，1917年", "p": ["这是一件高丽青瓷注子（有流和把手的酒器）。在胎上刻线、填入白土和黑土，再施釉烧成的“镶嵌”是高丽陶工的拿手技法。圆形的框里，柳树下坐着的两人以白色浮现出来。", "两人之间有一个棋盘，美术馆认为这一场面可与下围棋（韩语称“巴督”）的图像相比。琴、棋、书、画“四艺”被视为文人应有的修养，他们风雅的聚会也成了工艺品上的图案。描绘人物的高丽镶嵌青瓷十分罕见。"], "spots": [["棋盘", "两人之间的棋盘，用白土表现为方形。"], ["左边的人", "面向棋盘坐着的人。"], ["右边的人", "坐在对面的对手。"], ["柳", "垂在两人头上的柳枝，用黑土描绘。"], ["云纹框", "圆框四周环绕着卷云般的纹样。"], ["开片", "釉面细密的裂纹。烧成后冷却时，因胎与釉收缩程度不同而产生。"]]}, "zh-TW": {"title": "下棋人物紋鑲嵌青瓷注子", "artist": "作者不詳", "date": "13世紀", "place": "朝鮮半島（高麗）", "game": "圍棋（韓語「巴督」）", "medium": "青瓷，白土與黑土鑲嵌", "size": "高20.4公分，徑14.3公分", "credit": "約翰·L·塞弗倫斯捐贈，1917年", "p": ["這是一件高麗青瓷注子（有流和把手的酒器）。在胎上刻線、填入白土和黑土，再施釉燒成的「鑲嵌」是高麗陶工的拿手技法。圓形的框裡，柳樹下坐著的兩人以白色浮現出來。", "兩人之間有一個棋盤，美術館認為這一場面可與下圍棋（韓語稱「巴督」）的圖像相比。琴、棋、書、畫「四藝」被視為文人應有的修養，他們風雅的聚會也成了工藝品上的圖案。描繪人物的高麗鑲嵌青瓷十分罕見。"], "spots": [["棋盤", "兩人之間的棋盤，用白土表現為方形。"], ["左邊的人", "面向棋盤坐著的人。"], ["右邊的人", "坐在對面的對手。"], ["柳", "垂在兩人頭上的柳枝，用黑土描繪。"], ["雲紋框", "圓框四周環繞著捲雲般的紋樣。"], ["開片", "釉面細密的裂紋。燒成後冷卻時，因胎與釉收縮程度不同而產生。"]]}, "ko": {"title": "바둑 두는 인물무늬 상감 청자 주전자", "artist": "작자 미상", "date": "1200년대", "place": "한반도(고려)", "game": "바둑", "medium": "청자, 백토·흑토 상감", "size": "높이 20.4cm, 지름 14.3cm", "credit": "존 L. 세버런스 기증, 1917년", "p": ["고려 청자 주전자(주둥이와 손잡이가 있는 그릇)입니다. 그릇에 선을 새겨 흰 흙과 검은 흙을 메우고 유약을 입혀 굽는 ‘상감’은 고려 도공의 장기였습니다. 둥근 틀 안에 버드나무 아래 앉은 두 사람이 하얗게 떠오릅니다.", "두 사람 사이에는 판이 있고, 미술관은 이 장면을 바둑 두는 모습에 견줍니다. 거문고·바둑·글씨·그림의 ‘사예’는 문인이 갖추어야 할 교양으로 여겨졌고, 그 우아한 모임은 공예품의 무늬가 되기도 했습니다. 인물을 나타낸 고려 상감 청자는 드뭅니다."], "spots": [["판", "두 사람 사이의 판. 흰 흙으로 네모나게 나타냈습니다."], ["왼쪽 사람", "판을 향해 앉은 사람."], ["오른쪽 사람", "맞은편에 앉은 상대."], ["버드나무", "두 사람 머리 위로 늘어진 버들가지. 검은 흙으로 그렸습니다."], ["구름 틀", "둥근 틀 둘레를 소용돌이치는 구름 같은 무늬가 두릅니다."], ["빙렬", "유약 표면의 잔금(빙렬). 구운 뒤 식을 때 흙과 유약이 줄어드는 정도가 달라서 생깁니다."]]}, "es": {"title": "Jarra con figuras jugando al go, de celadón con incrustaciones", "artist": "Anónimo", "date": "Siglo XIII", "place": "Corea (dinastía Goryeo)", "game": "Go (baduk)", "medium": "Celadón con incrustaciones de engobe blanco y negro", "size": "Alt. 20,4 cm, diám. 14,3 cm", "credit": "Donación de John L. Severance, 1917", "p": ["Una jarra de celadón de Goryeo, con pico y asa. La incrustación —grabar líneas en el barro, rellenarlas de engobe blanco y negro y luego vidriar y cocer— era la especialidad de los alfareros de Goryeo; aquí, dentro de un marco redondo, dos figuras sentadas bajo un sauce resaltan en blanco.", "Entre ellas hay un tablero, y el museo compara la escena con las imágenes de partidas de go —baduk en coreano—. Tocar la cítara, el go, la caligrafía y la pintura eran las «cuatro artes» del letrado culto, y sus elegantes reuniones se convirtieron también en motivos para los artesanos. El celadón coreano con figuras humanas es poco común."], "spots": [["El tablero", "El tablero entre los dos, un cuadrado blanco."], ["La figura de la izquierda", "Sentada frente al tablero."], ["La figura de la derecha", "El rival, sentado enfrente."], ["El sauce", "Ramas de sauce cuelgan sobre ellos, dibujadas con engobe negro."], ["El marco de nubes", "Volutas como nubes rodean el marco redondo."], ["El craquelado", "Finas grietas en el vidriado. Se forman al enfriarse, porque el barro y el vidriado encogen de forma distinta."]]}, "fr": {"title": "Aiguière à décor incrusté de joueurs de go", "artist": "Anonyme", "date": "XIIIe siècle", "place": "Corée (dynastie Goryeo)", "game": "Go (baduk)", "medium": "Céladon à décor incrusté d’engobes blanc et noir", "size": "H. 20,4 cm, diam. 14,3 cm", "credit": "Don de John L. Severance, 1917", "p": ["Une aiguière en céladon de Goryeo, avec bec et anse. L’incrustation — graver des traits dans l’argile, les remplir d’engobe blanc et noir, puis émailler et cuire — était la spécialité des potiers de Goryeo ; ici, dans un médaillon, deux personnages assis sous un saule se détachent en blanc.", "Entre eux se trouve un plateau, et le musée rapproche la scène des images de parties de go — baduk en coréen. Jouer de la cithare, du go, pratiquer la calligraphie et la peinture formaient les « quatre arts » du lettré, dont les élégantes réunions devinrent aussi des motifs d’artisans. Le céladon coréen à figures humaines est rare."], "spots": [["Le plateau", "Le plateau entre les deux, un carré blanc."], ["Le personnage de gauche", "Assis face au plateau."], ["Le personnage de droite", "L’adversaire, assis en face."], ["Le saule", "Des branches de saule pendent au-dessus d’eux, tracées à l’engobe noir."], ["Le cadre de nuages", "Des volutes en forme de nuages entourent le médaillon."], ["Le craquelé", "De fines fissures dans la glaçure, nées au refroidissement, car argile et glaçure ne se rétractent pas autant."]]}, "pt": {"title": "Jarro de celadon com figuras a jogar go", "artist": "Autor desconhecido", "date": "Século XIII", "place": "Coreia (dinastia Goryeo)", "game": "Go (baduk)", "medium": "Celadon com incrustações de engobe branco e preto", "size": "Alt. 20,4 cm, diâm. 14,3 cm", "credit": "Doação de John L. Severance, 1917", "p": ["Um jarro de celadon de Goryeo, com bico e asa. A incrustação — gravar linhas no barro, enchê-las de engobe branco e preto e depois vidrar e cozer — era a especialidade dos oleiros de Goryeo; aqui, dentro de uma moldura redonda, duas figuras sentadas sob um salgueiro destacam-se a branco.", "Entre elas há um tabuleiro, e o museu compara a cena às imagens de partidas de go — baduk em coreano. Tocar cítara, jogar go, praticar caligrafia e pintura eram as «quatro artes» do letrado culto, e os seus encontros elegantes tornaram-se também motivos para artesãos. O celadon coreano com figuras humanas é raro."], "spots": [["O tabuleiro", "O tabuleiro entre os dois, um quadrado branco."], ["A figura à esquerda", "Sentada de frente para o tabuleiro."], ["A figura à direita", "O adversário, sentado em frente."], ["O salgueiro", "Ramos de salgueiro pendem sobre eles, desenhados a engobe preto."], ["A moldura de nuvens", "Volutas como nuvens rodeiam a moldura redonda."], ["O craquelado", "Finas fissuras no vidrado. Formam-se ao arrefecer, porque o barro e o vidrado encolhem de forma diferente."]]}, "de": {"title": "Kanne mit eingelegten Go-Spielern", "artist": "Unbekannt", "date": "13. Jahrhundert", "place": "Korea (Goryeo-Dynastie)", "game": "Go (Baduk)", "medium": "Seladon mit Einlagen aus weißem und schwarzem Schlicker", "size": "H. 20,4 cm, Dm. 14,3 cm", "credit": "Geschenk von John L. Severance, 1917", "p": ["Eine Seladonkanne der Goryeo-Zeit mit Tülle und Henkel. Die Einlagetechnik – Linien in den Ton ritzen, mit weißem und schwarzem Schlicker füllen, dann glasieren und brennen – war die Spezialität der Goryeo-Töpfer; hier heben sich in einem runden Medaillon zwei unter einer Weide sitzende Gestalten weiß ab.", "Zwischen ihnen liegt ein Brett, und das Museum vergleicht die Szene mit Bildern vom Go-Spiel – auf Koreanisch Baduk. Zither, Go, Kalligrafie und Malerei waren die „vier Künste“ des gebildeten Gelehrten, und ihre eleganten Zusammenkünfte wurden auch zu Motiven des Kunsthandwerks. Koreanisches Seladon mit Menschenfiguren ist selten."], "spots": [["Das Brett", "Das Brett zwischen den beiden, ein weißes Quadrat."], ["Die Gestalt links", "Sitzt dem Brett zugewandt."], ["Die Gestalt rechts", "Der Gegner, gegenüber sitzend."], ["Die Weide", "Weidenzweige hängen über ihnen, mit schwarzem Schlicker gezeichnet."], ["Der Wolkenrahmen", "Wolkenartige Ranken umlaufen das runde Medaillon."], ["Das Craquelé", "Feine Risse in der Glasur. Sie entstehen beim Abkühlen, weil Ton und Glasur verschieden stark schwinden."]]}, "ru": {"title": "Кувшин с инкрустированными фигурами игроков в го", "artist": "Неизвестный мастер", "date": "XIII век", "place": "Корея (династия Корё)", "game": "Го (падук)", "medium": "Селадон с инкрустацией белым и чёрным ангобом", "size": "Выс. 20,4 см, диам. 14,3 см", "credit": "Дар Джона Л. Северанса, 1917", "p": ["Селадоновый кувшин эпохи Корё с носиком и ручкой. Инкрустация — линии прорезают в глине, заполняют белым и чёрным ангобом, затем покрывают глазурью и обжигают — была коньком гончаров Корё; здесь в круглом медальоне белеют две фигуры, сидящие под ивой.", "Между ними доска, и музей сравнивает сцену с изображениями игры в го — по-корейски падук. Игра на цитре, го, каллиграфия и живопись считались «четырьмя искусствами» образованного книжника, и их изысканные собрания стали сюжетом и для ремесленников. Корейский селадон с фигурами людей встречается редко."], "spots": [["Доска", "Доска между ними — белый квадрат."], ["Фигура слева", "Сидит лицом к доске."], ["Фигура справа", "Соперник, сидящий напротив."], ["Ива", "Над ними свисают ветви ивы, нарисованные чёрным ангобом."], ["Облачная рамка", "Круглый медальон обрамляют завитки, похожие на облака."], ["Кракелюр", "Тонкие трещины в глазури. Они появляются при остывании, потому что глина и глазурь сжимаются по-разному."]]}, "tr": {"title": "Go oynayan figürlerle kakmalı seladon testi", "artist": "Bilinmiyor", "date": "13. yüzyıl", "place": "Kore (Goryeo hanedanı)", "game": "Go (baduk)", "medium": "Beyaz ve siyah astar kakmalı seladon", "size": "Yük. 20,4 cm, çap 14,3 cm", "credit": "John L. Severance bağışı, 1917", "p": ["Emzikli ve kulplu bir Goryeo seladon testisi. Kakma tekniği — kile çizgiler kazıyıp beyaz ve siyah astarla doldurmak, sonra sırlayıp pişirmek — Goryeo çömlekçilerinin ustalığıydı; burada yuvarlak bir çerçevenin içinde, söğüt altında oturan iki figür beyaz olarak belirir.", "Aralarında bir tahta var; müze sahneyi go (Korecede baduk) oynayanların resimlerine benzetir. Çalgı çalmak, go, hat ve resim, kültürlü bilginin “dört hüneri” sayılırdı ve zarif buluşmaları zanaatkârlar için de bir motif oldu. İnsan figürlü Kore seladonu nadirdir."], "spots": [["Tahta", "İkisinin arasındaki tahta, beyaz bir kare."], ["Soldaki figür", "Tahtaya dönük oturuyor."], ["Sağdaki figür", "Karşısında oturan rakip."], ["Söğüt", "Başlarının üstüne sarkan, siyah astarla çizilmiş söğüt dalları."], ["Bulut çerçeve", "Yuvarlak çerçevenin çevresini bulut gibi kıvrımlar dolanır."], ["Çatlaklar", "Sırdaki ince çatlaklar. Kil ile sır farklı oranda büzüldüğü için soğurken oluşur."]]}, "id": {"title": "Kendi seladon bertatah dengan pemain go", "artist": "Tidak diketahui", "date": "Abad ke-13", "place": "Korea (Dinasti Goryeo)", "game": "Go (baduk)", "medium": "Seladon dengan tatahan slip putih dan hitam", "size": "Tinggi 20,4 cm, diameter 14,3 cm", "credit": "Hibah John L. Severance, 1917", "p": ["Kendi seladon Goryeo dengan cerat dan pegangan. Teknik tatahan — menggores garis pada tanah liat, mengisinya dengan slip putih dan hitam, lalu mengglasir dan membakarnya — adalah keahlian khas perajin Goryeo; di sini, di dalam bingkai bundar, dua sosok yang duduk di bawah pohon dedalu tampak putih.", "Di antara mereka ada papan, dan museum membandingkan adegan ini dengan gambar orang bermain go — baduk dalam bahasa Korea. Bermain kecapi, go, kaligrafi, dan lukisan adalah “empat keahlian” cendekiawan terpelajar, dan pertemuan mereka yang anggun juga menjadi motif kerajinan. Seladon Korea bergambar manusia jarang ditemukan."], "spots": [["Papan", "Papan di antara keduanya, berupa kotak putih."], ["Sosok di kiri", "Duduk menghadap papan."], ["Sosok di kanan", "Lawannya, duduk di seberang."], ["Pohon dedalu", "Ranting dedalu menjuntai di atas mereka, digambar dengan slip hitam."], ["Bingkai awan", "Ulir seperti awan mengelilingi bingkai bundar."], ["Retak glasir", "Retakan halus pada glasir. Terbentuk saat mendingin karena tanah liat dan glasir menyusut berbeda."]]}, "hi": {"title": "गो खेलती आकृतियों वाला जड़ाऊ सेलाडॉन जग", "artist": "अज्ञात", "date": "1200 का दशक", "place": "कोरिया (गोर्यो राजवंश)", "game": "गो (बादुक)", "medium": "सफ़ेद और काली मिट्टी की जड़ाई वाला सेलाडॉन", "size": "ऊँचाई 20.4 सेमी, व्यास 14.3 सेमी", "credit": "जॉन एल. सेवरेंस का उपहार, 1917", "p": ["टोंटी और हत्थे वाला गोर्यो काल का सेलाडॉन जग। जड़ाई — मिट्टी में रेखाएँ खोदकर उनमें सफ़ेद और काली मिट्टी भरना, फिर चमक चढ़ाकर पकाना — गोर्यो के कुम्हारों की विशेषता थी; यहाँ एक गोल घेरे में विलो पेड़ के नीचे बैठी दो आकृतियाँ सफ़ेद उभरती हैं।", "उनके बीच एक बिसात है, और संग्रहालय इस दृश्य की तुलना गो (कोरियाई में बादुक) खेलने के चित्रों से करता है। वाद्य बजाना, गो, सुलेख और चित्रकला सुसंस्कृत विद्वान की ‘चार कलाएँ’ मानी जाती थीं, और उनकी सुरुचिपूर्ण सभाएँ शिल्पकारों के लिए भी नमूना बनीं। मनुष्य की आकृतियों वाला कोरियाई सेलाडॉन दुर्लभ है।"], "spots": [["बिसात", "दोनों के बीच की बिसात, एक सफ़ेद वर्ग।"], ["बाईं आकृति", "बिसात की ओर मुँह किए बैठी।"], ["दाईं आकृति", "सामने बैठा प्रतिद्वंद्वी।"], ["विलो", "उनके ऊपर झुकी विलो की डालियाँ, काली मिट्टी से बनी।"], ["बादलों का घेरा", "गोल घेरे के चारों ओर बादल जैसी कुंडलियाँ।"], ["दरारें", "चमक की सतह पर बारीक दरारें। ठंडा होते समय बनती हैं, क्योंकि मिट्टी और चमक अलग-अलग सिकुड़ती हैं।"]]}, "ar": {"title": "إبريق سيلادون مطعّم بشخصين يلعبان الغو", "artist": "مجهول", "date": "القرن الثالث عشر", "place": "كوريا (سلالة غوريو)", "game": "الغو (بادوك)", "medium": "سيلادون مطعّم بطين سائل أبيض وأسود", "size": "الارتفاع 20.4 سم، القطر 14.3 سم", "credit": "هدية جون ل. سيفيرانس، 1917", "p": ["إبريق من سيلادون غوريو له صنبور ومقبض. كان التطعيم — حفر الخطوط في الطين وملؤها بطين سائل أبيض وأسود ثم التزجيج والحرق — من براعات خزّافي غوريو؛ وهنا يبرز بالأبيض داخل إطار مستدير شخصان جالسان تحت شجرة صفصاف.", "بينهما رقعة، ويقارن المتحف المشهد بصور لعب الغو (البادوك بالكورية). كان العزف والغو والخط والرسم «الفنون الأربعة» للعالِم المثقف، وصارت مجالسهم الأنيقة زخارف للحرفيين أيضًا. والسيلادون الكوري الذي يصوّر البشر نادر."], "spots": [["الرقعة", "الرقعة بين الاثنين، مربع أبيض."], ["الشخص على اليسار", "جالس قبالة الرقعة."], ["الشخص على اليمين", "الخصم الجالس في المقابل."], ["الصفصاف", "أغصان صفصاف تتدلى فوقهما، مرسومة بالطين الأسود."], ["إطار السحب", "زخارف ملتفة كالسحب تحيط بالإطار المستدير."], ["التشقق", "شقوق دقيقة في الطلاء الزجاجي، تتكوّن عند التبريد لأن الطين والطلاء ينكمشان بقدر مختلف."]]}}, "kangra": {"ja": {"title": "露台でチャウパルをする2人", "artist": "作者不明", "date": "1790〜1800年ごろ", "place": "インド（パハーリー、カングラ派）", "game": "チャウパル", "medium": "素描、赤土（オーカー）による下描き", "size": "19.4×13.2cm", "credit": "エドワード・L・ウィッテモア基金による購入、1936年", "p": ["ヒマラヤのふもとのパハーリー地方、カングラの画家による素描です。赤い線（赤土の顔料）で下描きをし、その上を黒い線で整えています。色が塗られていないので、線の運びや人や道具の形がよくわかります。", "露台に座った男女が、十字の形の盤をはさんでチャウパルをしています。チャウパルはパチーシと同じ十字の盤を使う、インドで古くから遊ばれてきた競走のゲームで、長いさいころ（パーサ）を振って駒を進めます。盤にはまだ升目が描かれていません。2人のまわりでは侍女たちが仕えています。"], "spots": [["十字の盤", "床に置かれた十字形の盤。升目はまだ描かれていません。"], ["女性", "手のひらを上に向けた女性。さいころを振ろうとしているのでしょうか。"], ["男性", "羽根飾りのついたターバンの男性。盤のほうへ手をのばしています。"], ["左の侍女", "小さなびんを持ち、布をさしかけています。"], ["右の侍女", "長い柄の道具と小さな器を持っています。"], ["赤い下描き", "ターバンのまわりに、黒い線の下の赤い下描きが見えます。"]]}, "en": {"title": "Couple playing chaupar on a terrace", "artist": "Unknown", "date": "c. 1790–1800", "place": "India (Pahari, Kangra school)", "game": "Chaupar", "medium": "Drawing with red ochre underdrawing", "size": "19.4 × 13.2 cm", "credit": "Edward L. Whittemore Fund, 1936", "p": ["A drawing by an artist of Kangra, in the Pahari hills at the foot of the Himalayas. The first sketch was made in red (red ochre) and then refined in black. With no color laid over it, every line of the figures and their things can be followed.", "A man and a woman sit on a terrace on either side of a cross-shaped board, playing chaupar — an old Indian race game on the same cross as pachisi, moved by throwing long dice (pasa). The squares have not yet been drawn on the board. Attendants wait on the pair."], "spots": [["The cross-shaped board", "A board in the shape of a cross, on the floor. Its squares are not drawn yet."], ["The woman", "Her palm turned up — about to throw the dice?"], ["The man", "A turban with a plume; he reaches toward the board."], ["The attendant on the left", "She holds a small flask and stretches out a cloth."], ["The attendant on the right", "She holds a long-handled implement and a small vessel."], ["The red underdrawing", "Around the turban, the red first sketch shows beneath the black lines."]]}, "zh": {"title": "露台上玩乔帕尔的二人", "artist": "作者不详", "date": "约1790—1800年", "place": "印度（帕哈里，康格拉画派）", "game": "乔帕尔", "medium": "素描，赭红起稿", "size": "19.4×13.2厘米", "credit": "爱德华·L·惠特莫尔基金购藏，1936年", "p": ["这是喜马拉雅山麓帕哈里地区康格拉画家的素描。先用红线（赭红颜料）起稿，再用黑线修整。因为没有上色，人物和器物的线条一目了然。", "一男一女坐在露台上，隔着十字形的棋盘玩乔帕尔。乔帕尔与帕奇西使用同样的十字盘，是印度自古流行的竞走游戏，掷长骰（帕萨）来走棋。棋盘上还没有画出格子。侍女们在两人身旁侍候。"], "spots": [["十字棋盘", "放在地上的十字形棋盘，格子还没画。"], ["女子", "掌心朝上的女子，是要掷骰子吗？"], ["男子", "缠着带羽饰头巾的男子，把手伸向棋盘。"], ["左边的侍女", "她拿着小瓶，伸出一块布。"], ["右边的侍女", "她拿着长柄的器具和一个小容器。"], ["红色底稿", "头巾周围，黑线下面露出红色的底稿。"]]}, "zh-TW": {"title": "露台上玩喬帕爾的二人", "artist": "作者不詳", "date": "約1790—1800年", "place": "印度（帕哈里，康格拉畫派）", "game": "喬帕爾", "medium": "素描，赭紅起稿", "size": "19.4×13.2公分", "credit": "愛德華·L·惠特莫爾基金購藏，1936年", "p": ["這是喜馬拉雅山麓帕哈里地區康格拉畫家的素描。先用紅線（赭紅顏料）起稿，再用黑線修整。因為沒有上色，人物和器物的線條一目了然。", "一男一女坐在露台上，隔著十字形的棋盤玩喬帕爾。喬帕爾與帕奇西使用同樣的十字盤，是印度自古流行的競走遊戲，擲長骰（帕薩）來走棋。棋盤上還沒有畫出格子。侍女們在兩人身旁侍候。"], "spots": [["十字棋盤", "放在地上的十字形棋盤，格子還沒畫。"], ["女子", "掌心朝上的女子，是要擲骰子嗎？"], ["男子", "纏著帶羽飾頭巾的男子，把手伸向棋盤。"], ["左邊的侍女", "她拿著小瓶，伸出一塊布。"], ["右邊的侍女", "她拿著長柄的器具和一個小容器。"], ["紅色底稿", "頭巾周圍，黑線下面露出紅色的底稿。"]]}, "ko": {"title": "테라스에서 차우파르를 하는 두 사람", "artist": "작자 미상", "date": "1790~1800년경", "place": "인도(파하리, 캉그라파)", "game": "차우파르", "medium": "소묘, 붉은 오커 밑그림", "size": "19.4×13.2cm", "credit": "에드워드 L. 휘트모어 기금 구입, 1936년", "p": ["히말라야 기슭 파하리 지방, 캉그라 화가의 소묘입니다. 붉은 선(붉은 오커 안료)으로 밑그림을 그리고 그 위를 검은 선으로 다듬었습니다. 색을 칠하지 않아 선의 흐름과 사람·도구의 형태가 잘 보입니다.", "테라스에 앉은 남녀가 십자형 판을 사이에 두고 차우파르를 합니다. 차우파르는 파치시와 같은 십자형 판을 쓰는 인도의 오래된 경주 게임으로, 긴 주사위(파사)를 던져 말을 움직입니다. 판에는 아직 칸이 그려져 있지 않습니다. 두 사람 곁에서 시녀들이 시중을 듭니다."], "spots": [["십자형 판", "바닥에 놓인 십자형 판. 칸은 아직 그려져 있지 않습니다."], ["여성", "손바닥을 위로 한 여성. 주사위를 던지려는 걸까요?"], ["남성", "깃 장식을 단 터번의 남성. 판 쪽으로 손을 뻗습니다."], ["왼쪽 시녀", "작은 병을 들고 천을 내밀고 있습니다."], ["오른쪽 시녀", "자루가 긴 도구와 작은 그릇을 들고 있습니다."], ["붉은 밑그림", "터번 둘레에 검은 선 아래의 붉은 밑그림이 보입니다."]]}, "es": {"title": "Pareja jugando al chaupar en una terraza", "artist": "Anónimo", "date": "h. 1790–1800", "place": "India (Pahari, escuela de Kangra)", "game": "Chaupar", "medium": "Dibujo con boceto previo en ocre rojo", "size": "19,4 × 13,2 cm", "credit": "Edward L. Whittemore Fund, 1936", "p": ["Dibujo de un artista de Kangra, en las colinas pahari al pie del Himalaya. El primer boceto se hizo en rojo (ocre rojo) y luego se precisó en negro. Sin color encima, se puede seguir cada línea de las figuras y sus objetos.", "Un hombre y una mujer, sentados en una terraza a ambos lados de un tablero en cruz, juegan al chaupar, un antiguo juego de carreras indio sobre la misma cruz que el parchís (pachisi), que se mueve lanzando dados largos (pasa). Las casillas aún no están dibujadas en el tablero. Unas sirvientas atienden a la pareja."], "spots": [["El tablero en cruz", "Un tablero en forma de cruz, en el suelo. Sus casillas aún no están dibujadas."], ["La mujer", "Con la palma hacia arriba: ¿a punto de lanzar los dados?"], ["El hombre", "Turbante con penacho; tiende la mano hacia el tablero."], ["La sirvienta de la izquierda", "Sostiene un frasquito y extiende un paño."], ["La sirvienta de la derecha", "Sostiene un utensilio de mango largo y un recipiente pequeño."], ["El boceto rojo", "Alrededor del turbante, el boceto rojo asoma bajo las líneas negras."]]}, "fr": {"title": "Couple jouant au chaupar sur une terrasse", "artist": "Anonyme", "date": "v. 1790–1800", "place": "Inde (Pahari, école de Kangra)", "game": "Chaupar", "medium": "Dessin sur esquisse à l’ocre rouge", "size": "19,4 × 13,2 cm", "credit": "Edward L. Whittemore Fund, 1936", "p": ["Un dessin d’un artiste de Kangra, dans les collines pahari au pied de l’Himalaya. La première esquisse a été faite en rouge (ocre rouge), puis reprise en noir. Sans couleur par-dessus, on suit chaque trait des personnages et des objets.", "Un homme et une femme, assis sur une terrasse de part et d’autre d’un plateau en croix, jouent au chaupar, ancien jeu de course indien sur la même croix que le pachisi, où l’on avance en lançant de longs dés (pasa). Les cases ne sont pas encore tracées sur le plateau. Des servantes s’occupent du couple."], "spots": [["Le plateau en croix", "Un plateau en forme de croix, posé au sol. Ses cases ne sont pas encore tracées."], ["La femme", "La paume tournée vers le haut : sur le point de lancer les dés ?"], ["L’homme", "Turban à aigrette ; il tend la main vers le plateau."], ["La servante de gauche", "Elle tient un petit flacon et tend une étoffe."], ["La servante de droite", "Elle tient un ustensile à long manche et un petit récipient."], ["L’esquisse rouge", "Autour du turban, l’esquisse rouge apparaît sous les traits noirs."]]}, "pt": {"title": "Casal a jogar chaupar num terraço", "artist": "Autor desconhecido", "date": "c. 1790–1800", "place": "Índia (Pahari, escola de Kangra)", "game": "Chaupar", "medium": "Desenho com esboço prévio a ocre vermelho", "size": "19,4 × 13,2 cm", "credit": "Edward L. Whittemore Fund, 1936", "p": ["Desenho de um artista de Kangra, nas colinas pahari ao pé dos Himalaias. O primeiro esboço foi feito a vermelho (ocre vermelho) e depois afinado a preto. Sem cor por cima, pode seguir-se cada linha das figuras e dos objetos.", "Um homem e uma mulher, sentados num terraço de cada lado de um tabuleiro em cruz, jogam chaupar, antigo jogo de corrida indiano na mesma cruz do pachisi, em que se avança lançando dados compridos (pasa). As casas ainda não estão desenhadas no tabuleiro. Criadas servem o casal."], "spots": [["O tabuleiro em cruz", "Um tabuleiro em forma de cruz, no chão. As casas ainda não foram desenhadas."], ["A mulher", "Com a palma para cima: prestes a lançar os dados?"], ["O homem", "Turbante com penacho; estende a mão para o tabuleiro."], ["A criada à esquerda", "Segura um pequeno frasco e estende um pano."], ["A criada à direita", "Segura um utensílio de cabo comprido e um pequeno recipiente."], ["O esboço vermelho", "À volta do turbante, o esboço vermelho aparece sob as linhas pretas."]]}, "de": {"title": "Paar beim Chaupar auf einer Terrasse", "artist": "Unbekannt", "date": "um 1790–1800", "place": "Indien (Pahari, Kangra-Schule)", "game": "Chaupar", "medium": "Zeichnung mit Vorzeichnung in rotem Ocker", "size": "19,4 × 13,2 cm", "credit": "Edward L. Whittemore Fund, 1936", "p": ["Eine Zeichnung eines Künstlers aus Kangra in den Pahari-Bergen am Fuß des Himalaya. Die erste Skizze entstand in Rot (roter Ocker) und wurde dann in Schwarz ausgearbeitet. Da keine Farbe darüberliegt, lässt sich jede Linie der Figuren und Gegenstände verfolgen.", "Ein Mann und eine Frau sitzen auf einer Terrasse zu beiden Seiten eines kreuzförmigen Bretts und spielen Chaupar – ein altes indisches Laufspiel auf demselben Kreuz wie Pachisi, bei dem man mit langen Würfeln (Pasa) zieht. Die Felder sind auf dem Brett noch nicht eingezeichnet. Dienerinnen umsorgen das Paar."], "spots": [["Das Kreuzbrett", "Ein kreuzförmiges Brett auf dem Boden. Seine Felder sind noch nicht gezeichnet."], ["Die Frau", "Die Handfläche nach oben – gleich wirft sie die Würfel?"], ["Der Mann", "Turban mit Federbusch; er greift zum Brett."], ["Die Dienerin links", "Sie hält ein Fläschchen und reicht ein Tuch."], ["Die Dienerin rechts", "Sie hält ein langstieliges Gerät und ein kleines Gefäß."], ["Die rote Vorzeichnung", "Rund um den Turban schimmert die rote Skizze unter den schwarzen Linien hervor."]]}, "ru": {"title": "Пара, играющая в чаупар на террасе", "artist": "Неизвестный мастер", "date": "Ок. 1790–1800", "place": "Индия (Пахари, школа Кангры)", "game": "Чаупар", "medium": "Рисунок с подготовительным наброском красной охрой", "size": "19,4 × 13,2 см", "credit": "Фонд Эдварда Л. Уиттмора, 1936", "p": ["Рисунок художника из Кангры, в холмах Пахари у подножия Гималаев. Первый набросок сделан красным (красной охрой), затем уточнён чёрным. Красок поверх нет, и можно проследить каждую линию фигур и предметов.", "Мужчина и женщина сидят на террасе по обе стороны крестообразной доски и играют в чаупар — старинную индийскую игру-гонку на том же кресте, что и пачиси, где ходят, бросая длинные кости (паса). Клетки на доске ещё не нарисованы. Служанки прислуживают паре."], "spots": [["Крестообразная доска", "Доска в форме креста на полу. Клетки ещё не нарисованы."], ["Женщина", "Ладонь повёрнута вверх — сейчас бросит кости?"], ["Мужчина", "Тюрбан с плюмажем; он тянется к доске."], ["Служанка слева", "Держит маленький флакон и протягивает ткань."], ["Служанка справа", "Держит предмет на длинной ручке и небольшой сосуд."], ["Красный набросок", "Вокруг тюрбана из-под чёрных линий проступает красный набросок."]]}, "tr": {"title": "Terasta chaupar oynayan çift", "artist": "Bilinmiyor", "date": "y. 1790–1800", "place": "Hindistan (Pahari, Kangra okulu)", "game": "Chaupar", "medium": "Kırmızı aşı boyasıyla ön çizimli desen", "size": "19,4 × 13,2 cm", "credit": "Edward L. Whittemore Fund, 1936", "p": ["Himalayaların eteğindeki Pahari tepelerinde, Kangralı bir sanatçının deseni. İlk taslak kırmızıyla (kırmızı aşı boyası) yapılmış, sonra siyahla netleştirilmiş. Üstünde renk olmadığından figürlerin ve eşyaların her çizgisi izlenebilir.", "Bir terasta, haç biçimli bir tahtanın iki yanında oturan bir kadın ve bir erkek chaupar oynuyor; pachisi ile aynı haç üzerinde oynanan ve uzun zarlar (pasa) atılarak ilerlenen eski bir Hint yarış oyunu. Tahtaya kareler henüz çizilmemiş. Hizmetçiler çifte hizmet ediyor."], "spots": [["Haç biçimli tahta", "Yerde haç biçimli bir tahta. Kareleri henüz çizilmemiş."], ["Kadın", "Avucu yukarıda — zarları atmak üzere mi?"], ["Erkek", "Sorguçlu sarıklı; elini tahtaya uzatıyor."], ["Soldaki hizmetçi", "Küçük bir şişe tutuyor ve bir bez uzatıyor."], ["Sağdaki hizmetçi", "Uzun saplı bir alet ve küçük bir kap tutuyor."], ["Kırmızı taslak", "Sarığın çevresinde, siyah çizgilerin altından kırmızı taslak görünüyor."]]}, "id": {"title": "Pasangan bermain chaupar di teras", "artist": "Tidak diketahui", "date": "sekitar 1790–1800", "place": "India (Pahari, mazhab Kangra)", "game": "Chaupar", "medium": "Gambar dengan sketsa awal oker merah", "size": "19,4 × 13,2 cm", "credit": "Edward L. Whittemore Fund, 1936", "p": ["Gambar karya seniman Kangra, di perbukitan Pahari di kaki Himalaya. Sketsa pertama dibuat dengan merah (oker merah), lalu dirapikan dengan hitam. Tanpa warna di atasnya, setiap garis tokoh dan benda dapat diikuti.", "Seorang pria dan wanita duduk di teras di kedua sisi papan berbentuk salib, bermain chaupar — permainan balap kuno India di salib yang sama dengan pachisi, dimainkan dengan melempar dadu panjang (pasa). Petak-petaknya belum digambar di papan. Para pelayan melayani pasangan itu."], "spots": [["Papan salib", "Papan berbentuk salib di lantai. Petaknya belum digambar."], ["Sang wanita", "Telapak tangannya terbuka ke atas — hendak melempar dadu?"], ["Sang pria", "Bersorban dengan hiasan bulu; ia menjangkau papan."], ["Pelayan di kiri", "Memegang botol kecil dan mengulurkan kain."], ["Pelayan di kanan", "Memegang alat bergagang panjang dan wadah kecil."], ["Sketsa merah", "Di sekitar sorban, sketsa merah tampak di bawah garis hitam."]]}, "hi": {"title": "छत पर चौपड़ खेलता जोड़ा", "artist": "अज्ञात", "date": "लगभग 1790–1800", "place": "भारत (पहाड़ी, कांगड़ा शैली)", "game": "चौपड़", "medium": "लाल गेरू की आरंभिक रेखाओं वाला रेखाचित्र", "size": "19.4 × 13.2 सेमी", "credit": "एडवर्ड एल. व्हिटमोर फ़ंड, 1936", "p": ["हिमालय की तलहटी की पहाड़ियों में कांगड़ा के एक कलाकार का रेखाचित्र। पहला ख़ाका लाल (गेरू) से बना, फिर काले से निखारा गया। ऊपर रंग नहीं है, इसलिए आकृतियों और चीज़ों की हर रेखा देखी जा सकती है।", "छत पर बैठे एक पुरुष और एक स्त्री क्रॉस के आकार की बिसात के दोनों ओर चौपड़ खेल रहे हैं — पचीसी जैसे ही क्रॉस पर खेला जाने वाला पुराना भारतीय दौड़ का खेल, जिसमें लंबे पासे (पासा) फेंककर गोटियाँ चलाई जाती हैं। बिसात पर अभी खाने नहीं बने हैं। दासियाँ जोड़े की सेवा में हैं।"], "spots": [["क्रॉस वाली बिसात", "फ़र्श पर रखी क्रॉस आकार की बिसात। इसके खाने अभी नहीं बने।"], ["स्त्री", "हथेली ऊपर की ओर — क्या वह पासा फेंकने वाली है?"], ["पुरुष", "कलगी वाली पगड़ी; वह बिसात की ओर हाथ बढ़ाता है।"], ["बाईं दासी", "छोटी शीशी थामे, कपड़ा आगे बढ़ाती है।"], ["दाईं दासी", "लंबी डंडी वाला उपकरण और छोटा पात्र थामे है।"], ["लाल ख़ाका", "पगड़ी के आसपास काली रेखाओं के नीचे लाल ख़ाका दिखता है।"]]}, "ar": {"title": "زوجان يلعبان التشوبار على شرفة", "artist": "مجهول", "date": "نحو 1790–1800", "place": "الهند (باهاري، مدرسة كانغرا)", "game": "التشوبار", "medium": "رسم بخطوط أولية بالمغرة الحمراء", "size": "19.4 × 13.2 سم", "credit": "صندوق إدوارد ل. ويتمور، 1936", "p": ["رسم لفنان من كانغرا في تلال باهاري عند سفوح الهيمالايا. رُسم التخطيط الأول بالأحمر (المغرة الحمراء) ثم ضُبط بالأسود. ولأنه بلا ألوان فوقه، يمكن تتبّع كل خط في الأشخاص والأشياء.", "يجلس رجل وامرأة على شرفة على جانبي رقعة على شكل صليب، يلعبان التشوبار، وهي لعبة سباق هندية قديمة على الصليب نفسه الذي تُلعب عليه الباتشيسي، تُحرَّك فيها القطع برمي نرد طويل (باسا). لم تُرسم الخانات على الرقعة بعد. وتقوم وصيفات على خدمة الزوجين."], "spots": [["الرقعة الصليبية", "رقعة على شكل صليب على الأرض، لم تُرسم خاناتها بعد."], ["المرأة", "كفّها إلى الأعلى — هل ستلقي النرد؟"], ["الرجل", "عمامة بريشة؛ يمد يده نحو الرقعة."], ["الوصيفة على اليسار", "تحمل قارورة صغيرة وتمد قطعة قماش."], ["الوصيفة على اليمين", "تحمل أداة طويلة المقبض ووعاء صغيرًا."], ["التخطيط الأحمر", "حول العمامة يظهر التخطيط الأحمر تحت الخطوط السوداء."]]}}, "vuillard": {"ja": {"title": "チェッカーの一局（『風景と室内』より）", "artist": "エドゥアール・ヴュイヤール", "date": "1899年", "place": "フランス", "game": "チェッカー", "medium": "多色リトグラフ（第3ステート）。刷りはオーギュスト・クロ、版元はアンブロワーズ・ヴォラール", "size": "図33×25.7cm（紙38×30.8cm）", "credit": "ハンナ基金寄贈、1951年", "p": ["画商のアンブロワーズ・ヴォラールは、版画の版元でもありました。1895年にボナールに12枚の色刷りリトグラフの画集を頼んだのを手はじめに、次々と画集を出しました。ヴュイヤールの『風景と室内』もそのひとつで、刷ったのは名刷り師オーギュスト・クロです。", "ヴュイヤールとボナールは「ナビ派」（ヘブライ語で「預言者」）と呼ばれた画家の仲間で、形と色そのもので気持ちを表す新しい絵をめざし、都会の暮らしや家族の団らんを好んで描きました。模様で埋めつくされた部屋で、男たちがチェッカーの盤をはさみ、女性が立ったまま勝負を見守っています。フランス語でチェッカーは「ダーム」。左下の鉛筆書きは「ダームの一局」と読めます。"], "spots": [["盤", "市松の小さな盤。駒が並んでいるのが見えます。"], ["左の男", "ひげの男が、盤の上に手をのばしています。"], ["右の男", "向かいの肘掛け椅子で、うつむいて盤を見つめる相手。立っている女性のかげになっています。"], ["立つ女性", "あごに手を当てて、勝負の行方を見守ります。"], ["ランプ", "壁ぎわのランプ。壁紙も椅子の布も、模様でいっぱいです。"], ["鉛筆の書き込み", "左下に鉛筆で「partie de dames（ダームの一局）」と書かれています。"]]}, "en": {"title": "The Game of Checkers (from Landscapes and Interiors)", "artist": "Édouard Vuillard", "date": "1899", "place": "France", "game": "Checkers", "medium": "Color lithograph (state III/III); printed by Auguste Clot, published by Ambroise Vollard", "size": "Image 33 × 25.7 cm (sheet 38 × 30.8 cm)", "credit": "Gift of the Hanna Fund, 1951", "p": ["Ambroise Vollard, a dealer in Impressionist paintings, was also an important publisher of prints. In 1895 he commissioned a portfolio of 12 color lithographs from Pierre Bonnard, and many more albums followed — among them Vuillard’s Landscapes and Interiors, printed by the master printer Auguste Clot.", "Bonnard and Vuillard belonged to the Nabis — Hebrew for “prophets” — who sought a new art in which form and color themselves carried feeling, and who loved scenes of city life and middle-class home life. In a room crowded with pattern, two men face each other over a checkers board while a woman stands and watches. In French, checkers is “dames”; the pencil note at lower left reads “partie de dames”, a game of checkers."], "spots": [["The board", "A small checkered board, with the pieces set out on it."], ["The man on the left", "A bearded man reaches out over the board."], ["The man on the right", "His opponent, bent over the board in an armchair, half hidden by the standing woman."], ["The standing woman", "Hand to her chin, she follows the game."], ["The lamp", "A lamp by the wall. Wallpaper and upholstery alike are full of pattern."], ["The pencil note", "At lower left, in pencil: “partie de dames” — a game of checkers."]]}, "zh": {"title": "跳棋对局（选自《风景与室内》）", "artist": "爱德华·维亚尔", "date": "1899年", "place": "法国", "game": "西洋跳棋", "medium": "彩色石版画（第3版次）；奥古斯特·克洛印制，安布鲁瓦兹·沃拉尔出版", "size": "画面33×25.7厘米（纸张38×30.8厘米）", "credit": "汉纳基金捐赠，1951年", "p": ["画商安布鲁瓦兹·沃拉尔也是重要的版画出版人。1895年他请博纳尔创作了12幅彩色石版画的画集，此后又接连出版多部画集，维亚尔的《风景与室内》便是其中之一，由名印刷师奥古斯特·克洛印制。", "博纳尔和维亚尔同属“纳比派”（希伯来语意为“先知”），他们追求以形与色本身来表达情感的新艺术，喜欢描绘都市生活与家庭日常。在满是花纹的房间里，两个男人隔着跳棋盘对弈，一位女子站着观战。法语把跳棋叫作“dames”，左下角的铅笔字可读作“partie de dames”，即“一局跳棋”。"], "spots": [["棋盘", "小小的方格棋盘，上面摆着棋子。"], ["左边的男人", "留胡子的男人把手伸向棋盘。"], ["右边的男人", "对手坐在扶手椅上低头看棋，被站着的女子挡住了一半。"], ["站着的女子", "她手托下巴，关注着胜负。"], ["灯", "墙边的灯。壁纸和椅子的布面都布满花纹。"], ["铅笔字", "左下角用铅笔写着“partie de dames”（一局跳棋）。"]]}, "zh-TW": {"title": "跳棋對局（選自《風景與室內》）", "artist": "愛德華·維亞爾", "date": "1899年", "place": "法國", "game": "西洋跳棋", "medium": "彩色石版畫（第3版次）；奧古斯特·克洛印製，安布魯瓦茲·沃拉爾出版", "size": "畫面33×25.7公分（紙張38×30.8公分）", "credit": "漢納基金捐贈，1951年", "p": ["畫商安布魯瓦茲·沃拉爾也是重要的版畫出版人。1895年他請波納爾創作了12幅彩色石版畫的畫集，此後又接連出版多部畫集，維亞爾的《風景與室內》便是其中之一，由名印刷師奧古斯特·克洛印製。", "波納爾和維亞爾同屬「那比派」（希伯來語意為「先知」），他們追求以形與色本身來表達情感的新藝術，喜歡描繪都市生活與家庭日常。在滿是花紋的房間裡，兩個男人隔著跳棋盤對弈，一位女子站著觀戰。法語把跳棋叫作「dames」，左下角的鉛筆字可讀作「partie de dames」，即「一局跳棋」。"], "spots": [["棋盤", "小小的方格棋盤，上面擺著棋子。"], ["左邊的男人", "留鬍子的男人把手伸向棋盤。"], ["右邊的男人", "對手坐在扶手椅上低頭看棋，被站著的女子擋住了一半。"], ["站著的女子", "她手托下巴，關注著勝負。"], ["燈", "牆邊的燈。壁紙和椅子的布面都布滿花紋。"], ["鉛筆字", "左下角用鉛筆寫著「partie de dames」（一局跳棋）。"]]}, "ko": {"title": "체커 한 판 (『풍경과 실내』 중에서)", "artist": "에두아르 뷔야르", "date": "1899년", "place": "프랑스", "game": "체커", "medium": "다색 석판화(제3스테이트). 인쇄 오귀스트 클로, 발행 앙브루아즈 볼라르", "size": "화면 33×25.7cm(종이 38×30.8cm)", "credit": "해나 기금 기증, 1951년", "p": ["화상 앙브루아즈 볼라르는 판화 발행인이기도 했습니다. 1895년 보나르에게 12점의 컬러 석판화 화집을 맡긴 것을 시작으로 화집을 잇달아 냈고, 뷔야르의 『풍경과 실내』도 그중 하나입니다. 인쇄는 명인 오귀스트 클로가 맡았습니다.", "보나르와 뷔야르는 ‘나비파’(히브리어로 ‘예언자’)라 불린 화가 모임의 일원으로, 형태와 색 자체로 감정을 표현하는 새로운 그림을 추구하며 도시의 삶과 가족의 일상을 즐겨 그렸습니다. 무늬로 가득한 방에서 두 남자가 체커판을 사이에 두고 마주 앉고, 한 여성이 선 채로 승부를 지켜봅니다. 프랑스어로 체커는 ‘담(dames)’이며, 왼쪽 아래의 연필 글씨는 ‘partie de dames(체커 한 판)’로 읽힙니다."], "spots": [["판", "작은 체크무늬 판. 말이 놓여 있는 것이 보입니다."], ["왼쪽 남자", "수염 난 남자가 판 위로 손을 뻗습니다."], ["오른쪽 남자", "안락의자에서 고개를 숙여 판을 보는 상대. 서 있는 여성에게 반쯤 가려져 있습니다."], ["서 있는 여성", "턱에 손을 괴고 승부를 지켜봅니다."], ["램프", "벽가의 램프. 벽지도 의자 천도 무늬로 가득합니다."], ["연필 글씨", "왼쪽 아래에 연필로 ‘partie de dames(체커 한 판)’라고 쓰여 있습니다."]]}, "es": {"title": "La partida de damas (de Paisajes e interiores)", "artist": "Édouard Vuillard", "date": "1899", "place": "Francia", "game": "Damas", "medium": "Litografía en color (estado III/III); impresa por Auguste Clot, editada por Ambroise Vollard", "size": "Imagen 33 × 25,7 cm (hoja 38 × 30,8 cm)", "credit": "Donación del Hanna Fund, 1951", "p": ["Ambroise Vollard, marchante de pintura impresionista, fue también un importante editor de grabados. En 1895 encargó a Pierre Bonnard un álbum de 12 litografías en color y después publicó muchos más, entre ellos Paisajes e interiores de Vuillard, impreso por el maestro impresor Auguste Clot.", "Bonnard y Vuillard formaban parte de los nabis —«profetas» en hebreo—, que buscaban un arte nuevo en el que la forma y el color expresaran por sí mismos el sentimiento, y que amaban las escenas de la vida urbana y familiar. En una habitación llena de motivos, dos hombres se enfrentan ante un tablero de damas mientras una mujer, de pie, observa. En francés el juego se llama «dames»; la nota a lápiz abajo a la izquierda dice «partie de dames», una partida de damas."], "spots": [["El tablero", "Un pequeño tablero a cuadros, con las piezas colocadas."], ["El hombre de la izquierda", "Un hombre con barba extiende la mano sobre el tablero."], ["El hombre de la derecha", "Su rival, inclinado sobre el tablero en un sillón, medio oculto por la mujer de pie."], ["La mujer de pie", "Con la mano en la barbilla, sigue la partida."], ["La lámpara", "Una lámpara junto a la pared. El papel pintado y la tapicería están llenos de motivos."], ["La nota a lápiz", "Abajo a la izquierda, a lápiz: «partie de dames», una partida de damas."]]}, "fr": {"title": "La Partie de dames (de Paysages et Intérieurs)", "artist": "Édouard Vuillard", "date": "1899", "place": "France", "game": "Dames", "medium": "Lithographie en couleurs (état III/III) ; imprimée par Auguste Clot, éditée par Ambroise Vollard", "size": "Image 33 × 25,7 cm (feuille 38 × 30,8 cm)", "credit": "Don du Hanna Fund, 1951", "p": ["Ambroise Vollard, marchand de tableaux impressionnistes, fut aussi un grand éditeur d’estampes. En 1895, il commanda à Pierre Bonnard un album de 12 lithographies en couleurs, puis en publia bien d’autres, dont Paysages et Intérieurs de Vuillard, imprimé par le maître imprimeur Auguste Clot.", "Bonnard et Vuillard faisaient partie des nabis — « prophètes » en hébreu —, qui cherchaient un art nouveau où la forme et la couleur expriment elles-mêmes le sentiment, et qui aimaient les scènes de la vie urbaine et familiale. Dans une pièce saturée de motifs, deux hommes s’affrontent au-dessus d’un damier tandis qu’une femme, debout, regarde. La note au crayon, en bas à gauche, se lit « partie de dames »."], "spots": [["Le damier", "Un petit damier, les pions en place."], ["L’homme de gauche", "Un homme barbu avance la main au-dessus du damier."], ["L’homme de droite", "Son adversaire, penché sur le jeu dans un fauteuil, à moitié caché par la femme debout."], ["La femme debout", "La main au menton, elle suit la partie."], ["La lampe", "Une lampe contre le mur. Papier peint et tissus sont couverts de motifs."], ["La note au crayon", "En bas à gauche, au crayon : « partie de dames »."]]}, "pt": {"title": "A partida de damas (de Paisagens e interiores)", "artist": "Édouard Vuillard", "date": "1899", "place": "França", "game": "Damas", "medium": "Litografia a cores (estado III/III); impressa por Auguste Clot, editada por Ambroise Vollard", "size": "Imagem 33 × 25,7 cm (folha 38 × 30,8 cm)", "credit": "Doação do Hanna Fund, 1951", "p": ["Ambroise Vollard, comerciante de pintura impressionista, foi também um importante editor de gravuras. Em 1895 encomendou a Pierre Bonnard um álbum de 12 litografias a cores e depois publicou muitos outros, entre eles Paisagens e interiores, de Vuillard, impresso pelo mestre impressor Auguste Clot.", "Bonnard e Vuillard pertenciam aos nabis — «profetas» em hebraico —, que procuravam uma arte nova em que a forma e a cor exprimissem por si o sentimento, e que gostavam de cenas da vida urbana e familiar. Numa sala cheia de padrões, dois homens enfrentam-se diante de um tabuleiro de damas enquanto uma mulher, de pé, observa. Em francês o jogo chama-se «dames»; a nota a lápis no canto inferior esquerdo diz «partie de dames», uma partida de damas."], "spots": [["O tabuleiro", "Um pequeno tabuleiro xadrezado, com as peças dispostas."], ["O homem à esquerda", "Um homem de barba estende a mão sobre o tabuleiro."], ["O homem à direita", "O adversário, debruçado sobre o tabuleiro numa poltrona, meio escondido pela mulher de pé."], ["A mulher de pé", "Com a mão no queixo, acompanha a partida."], ["O candeeiro", "Um candeeiro junto à parede. Papel de parede e estofos estão cheios de padrões."], ["A nota a lápis", "No canto inferior esquerdo, a lápis: «partie de dames», uma partida de damas."]]}, "de": {"title": "Die Damepartie (aus Landschaften und Interieurs)", "artist": "Édouard Vuillard", "date": "1899", "place": "Frankreich", "game": "Dame", "medium": "Farblithografie (Zustand III/III); gedruckt von Auguste Clot, verlegt von Ambroise Vollard", "size": "Bild 33 × 25,7 cm (Blatt 38 × 30,8 cm)", "credit": "Geschenk des Hanna Fund, 1951", "p": ["Ambroise Vollard, Händler impressionistischer Malerei, war auch ein bedeutender Verleger von Druckgrafik. 1895 gab er bei Pierre Bonnard eine Mappe mit 12 Farblithografien in Auftrag; viele weitere folgten, darunter Vuillards Landschaften und Interieurs, gedruckt vom Meisterdrucker Auguste Clot.", "Bonnard und Vuillard gehörten zu den Nabis – hebräisch für „Propheten“ –, die eine neue Kunst suchten, in der Form und Farbe selbst Gefühl ausdrücken, und die Szenen aus dem Stadt- und Familienleben liebten. In einem Raum voller Muster sitzen sich zwei Männer am Damebrett gegenüber, eine Frau steht daneben und schaut zu. Auf Französisch heißt das Spiel „dames“; die Bleistiftnotiz unten links lautet „partie de dames“, eine Damepartie."], "spots": [["Das Brett", "Ein kleines kariertes Brett mit den aufgestellten Steinen."], ["Der Mann links", "Ein bärtiger Mann greift über das Brett."], ["Der Mann rechts", "Sein Gegner, im Sessel über das Brett gebeugt, halb verdeckt von der stehenden Frau."], ["Die stehende Frau", "Die Hand am Kinn, verfolgt sie die Partie."], ["Die Lampe", "Eine Lampe an der Wand. Tapete und Polster sind voller Muster."], ["Die Bleistiftnotiz", "Unten links mit Bleistift: „partie de dames“ – eine Damepartie."]]}, "ru": {"title": "Партия в шашки (из альбома «Пейзажи и интерьеры»)", "artist": "Эдуар Вюйяр", "date": "1899", "place": "Франция", "game": "Шашки", "medium": "Цветная литография (состояние III/III); печать Огюста Кло, издатель Амбруаз Воллар", "size": "Изображение 33 × 25,7 см (лист 38 × 30,8 см)", "credit": "Дар фонда Ханны, 1951", "p": ["Амбруаз Воллар, торговец картинами импрессионистов, был и крупным издателем гравюр. В 1895 году он заказал Пьеру Боннару альбом из 12 цветных литографий, а затем выпустил ещё много альбомов, среди них «Пейзажи и интерьеры» Вюйяра, отпечатанные мастером-печатником Огюстом Кло.", "Боннар и Вюйяр входили в группу «наби» («пророки» на иврите), искавшую новое искусство, где сами форма и цвет выражают чувство, и любили сцены городской и семейной жизни. В комнате, сплошь покрытой узорами, двое мужчин сидят над шашечной доской, а женщина стоя следит за игрой. По-французски шашки — «dames»; карандашная надпись внизу слева читается как «partie de dames», партия в шашки."], "spots": [["Доска", "Маленькая клетчатая доска с расставленными шашками."], ["Мужчина слева", "Бородатый мужчина протягивает руку над доской."], ["Мужчина справа", "Его соперник склонился над доской в кресле; его наполовину заслоняет стоящая женщина."], ["Стоящая женщина", "Подперев подбородок рукой, она следит за партией."], ["Лампа", "Лампа у стены. Обои и обивка полны узоров."], ["Карандашная надпись", "Внизу слева карандашом: «partie de dames» — партия в шашки."]]}, "tr": {"title": "Dama Oyunu (Manzaralar ve İç Mekânlar’dan)", "artist": "Édouard Vuillard", "date": "1899", "place": "Fransa", "game": "Dama", "medium": "Renkli litografi (III/III. durum); baskı Auguste Clot, yayımcı Ambroise Vollard", "size": "Görüntü 33 × 25,7 cm (kâğıt 38 × 30,8 cm)", "credit": "Hanna Fund bağışı, 1951", "p": ["İzlenimci resim satıcısı Ambroise Vollard aynı zamanda önemli bir baskı yayımcısıydı. 1895’te Pierre Bonnard’a 12 renkli litografiden oluşan bir albüm ısmarladı; ardından pek çok albüm daha yayımladı. Vuillard’ın Manzaralar ve İç Mekânlar’ı da bunlardan biridir ve usta baskıcı Auguste Clot tarafından basılmıştır.", "Bonnard ve Vuillard, İbranicede “peygamberler” anlamına gelen Nabiler grubundandı. Biçim ve rengin kendisiyle duygu anlatan yeni bir sanat arıyor, kent ve aile yaşamından sahneleri seviyorlardı. Desenlerle dolu bir odada iki adam dama tahtasının başında karşılıklı oturuyor, ayaktaki bir kadın oyunu izliyor. Fransızcada dama “dames” diye anılır; sol alttaki kurşun kalem notu “partie de dames”, yani “bir dama oyunu” diye okunur."], "spots": [["Tahta", "Taşları dizilmiş küçük, kareli bir tahta."], ["Soldaki adam", "Sakallı bir adam elini tahtanın üzerine uzatıyor."], ["Sağdaki adam", "Rakibi, koltukta tahtaya eğilmiş; ayaktaki kadın onu yarı yarıya kapatıyor."], ["Ayaktaki kadın", "Elini çenesine dayamış, oyunu izliyor."], ["Lamba", "Duvarın yanında bir lamba. Duvar kâğıdı da döşeme de desenle dolu."], ["Kurşun kalem notu", "Sol altta kurşun kalemle: “partie de dames” — bir dama oyunu."]]}, "id": {"title": "Permainan Dam (dari Pemandangan dan Interior)", "artist": "Édouard Vuillard", "date": "1899", "place": "Prancis", "game": "Dam", "medium": "Litografi berwarna (state III/III); dicetak oleh Auguste Clot, diterbitkan oleh Ambroise Vollard", "size": "Gambar 33 × 25,7 cm (kertas 38 × 30,8 cm)", "credit": "Hibah Hanna Fund, 1951", "p": ["Ambroise Vollard, pedagang lukisan impresionis, juga penerbit cetakan grafis yang penting. Pada 1895 ia memesan album 12 litografi berwarna dari Pierre Bonnard, lalu menerbitkan banyak album lain, di antaranya Pemandangan dan Interior karya Vuillard yang dicetak oleh master pencetak Auguste Clot.", "Bonnard dan Vuillard termasuk kelompok Nabis — “para nabi” dalam bahasa Ibrani — yang mencari seni baru tempat bentuk dan warna sendiri mengungkapkan perasaan, dan gemar melukis kehidupan kota serta keluarga. Di ruangan yang penuh motif, dua pria berhadapan di depan papan dam sementara seorang wanita berdiri menonton. Dalam bahasa Prancis permainan ini disebut “dames”; catatan pensil di kiri bawah berbunyi “partie de dames”, satu permainan dam."], "spots": [["Papan", "Papan kotak-kotak kecil dengan bidak yang tersusun."], ["Pria di kiri", "Pria berjanggut mengulurkan tangan ke atas papan."], ["Pria di kanan", "Lawannya membungkuk di atas papan di kursi berlengan, setengah tertutup wanita yang berdiri."], ["Wanita yang berdiri", "Dengan tangan di dagu, ia mengikuti permainan."], ["Lampu", "Lampu di dekat dinding. Kertas dinding dan pelapis kursi penuh motif."], ["Catatan pensil", "Di kiri bawah dengan pensil: “partie de dames” — satu permainan dam."]]}, "hi": {"title": "चेकर्स का खेल (‘भूदृश्य और भीतरी कक्ष’ से)", "artist": "एदुआर वुइयार", "date": "1899", "place": "फ़्रांस", "game": "चेकर्स", "medium": "रंगीन लिथोग्राफ़ (स्टेट III/III); छपाई ओग्युस्त क्लो, प्रकाशक आम्ब्रुआज़ वोलार", "size": "चित्र 33 × 25.7 सेमी (काग़ज़ 38 × 30.8 सेमी)", "credit": "हैना फ़ंड का उपहार, 1951", "p": ["इंप्रेशनिस्ट चित्रों के व्यापारी आम्ब्रुआज़ वोलार छापों के बड़े प्रकाशक भी थे। 1895 में उन्होंने पियर बोनार से 12 रंगीन लिथोग्राफ़ का एक एल्बम बनवाया और फिर कई और एल्बम छापे — इन्हीं में वुइयार का ‘भूदृश्य और भीतरी कक्ष’ है, जिसे कुशल मुद्रक ओग्युस्त क्लो ने छापा।", "बोनार और वुइयार ‘नबी’ (हिब्रू में ‘पैग़ंबर’) नाम के कलाकार-समूह से थे, जो ऐसी नई कला चाहते थे जिसमें आकार और रंग ख़ुद भावना कहें, और जिन्हें शहर और घर-परिवार के दृश्य प्रिय थे। नमूनों से भरे कमरे में दो आदमी चेकर्स की बिसात के आमने-सामने हैं और एक महिला खड़ी होकर खेल देख रही है। फ़्रांसीसी में चेकर्स को ‘दाम’ कहते हैं; नीचे बाईं ओर पेंसिल से लिखा है ‘partie de dames’ — चेकर्स की एक बाज़ी।"], "spots": [["बिसात", "छोटी चौख़ानेदार बिसात, जिस पर गोटियाँ रखी हैं।"], ["बाईं ओर का आदमी", "दाढ़ी वाला आदमी बिसात के ऊपर हाथ बढ़ाता है।"], ["दाईं ओर का आदमी", "उसका प्रतिद्वंद्वी, आरामकुर्सी में बिसात पर झुका, खड़ी महिला के पीछे आधा छिपा।"], ["खड़ी महिला", "ठोड़ी पर हाथ रखे वह खेल देखती है।"], ["लैंप", "दीवार के पास लैंप। वॉलपेपर और गद्दी दोनों नमूनों से भरे हैं।"], ["पेंसिल का लेख", "नीचे बाईं ओर पेंसिल से: ‘partie de dames’ — चेकर्स की एक बाज़ी।"]]}, "ar": {"title": "دور في لعبة الداما (من «مناظر وأماكن داخلية»)", "artist": "إدوار فويار", "date": "1899", "place": "فرنسا", "game": "الداما", "medium": "طباعة حجرية ملوّنة (الحالة الثالثة من ثلاث)؛ طبعها أوغست كلو ونشرها أمبرواز فولار", "size": "الصورة 33 × 25.7 سم (الورقة 38 × 30.8 سم)", "credit": "هدية صندوق هانا، 1951", "p": ["كان أمبرواز فولار، تاجر لوحات الانطباعيين، ناشرًا مهمًا للمطبوعات الفنية أيضًا. ففي 1895 طلب من بيير بونار ألبومًا من 12 طبعة حجرية ملوّنة، ثم نشر ألبومات كثيرة أخرى، منها «مناظر وأماكن داخلية» لفويار، وقد طبعه الطبّاع البارع أوغست كلو.", "كان بونار وفويار من جماعة «النبيّين» (أي «الأنبياء» بالعبرية) التي سعت إلى فن جديد يعبّر فيه الشكل واللون بذاتهما عن الشعور، وأحبّت مشاهد المدينة والحياة العائلية. في غرفة تغمرها الزخارف يجلس رجلان متقابلين أمام رقعة الداما، بينما تقف امرأة تتابع اللعب. تُسمّى الداما بالفرنسية «dames»، والكتابة بالقلم الرصاص في أسفل اليسار تُقرأ «partie de dames» أي دور في الداما."], "spots": [["الرقعة", "رقعة مربعات صغيرة صُفّت عليها القطع."], ["الرجل على اليسار", "رجل ملتحٍ يمد يده فوق الرقعة."], ["الرجل على اليمين", "خصمه، منحنٍ على الرقعة في كرسي بذراعين، تحجبه المرأة الواقفة نصف حجب."], ["المرأة الواقفة", "يدها على ذقنها، تتابع اللعب."], ["المصباح", "مصباح قرب الجدار. ورق الجدران والمفروشات مليئة بالزخارف."], ["كتابة القلم الرصاص", "في أسفل اليسار بالقلم الرصاص: «partie de dames» — دور في الداما."]]}}};
  Object.keys(A).forEach(id => Object.keys(A[id]).forEach(l => { if (T[l]) T[l][id] = A[id][l]; })); })(window.MUSEUM_PAINT_T);
